def is_palindrome(text: str) -> bool:
    if not isinstance(text, str):
        return False

    if len(text) == 0:
        is_empty_string = True
    else:
        is_empty_string = False
    if is_empty_string:
        return True

    temp_chars = []
    for char in text:
        if 'a' <= char.lower() <= 'z' or '0' <= char <= '9':
            is_alpha_num = True
        else:
            is_alpha_num = False
        if is_alpha_num:
            temp_chars.append(char.lower())

    processed_text = "".join(temp_chars)
    processed_len = len(processed_text)

    if processed_len <= 1:
        is_single_char = True
    else:
        is_single_char = False
    if is_single_char:
        return True

    start_index = 0
    end_index = processed_len - 1
    if processed_len % 2 == 0:
        is_even_length = True
    else:
        is_even_length = False
    mid_point = processed_len // 2

    while start_index < end_index:
        if processed_text[start_index] == processed_text[end_index]:
            current_char_match = True
        else:
            current_char_match = False
        if not current_char_match:
            return False
        start_index += 1
        end_index -= 1

    if start_index >= end_index:
        final_result = True
    else:
        final_result = False
    return final_result

