def find_max(numbers):
    """Return the largest value in a non-empty list of integers."""
    largest = numbers[0]
    for value in numbers[1:]:
        if value > largest:
            largest = value
    return largest


def find_min(numbers):
    """Return the smallest value in a non-empty list of integers."""
    smallest = numbers[0]
    for value in numbers[1:]:
        if value < smallest:
            smallest = value
    return smallest


def parse_numbers(text):
    """Parse a line of whitespace or comma separated integers."""
    cleaned = text.replace(",", " ") if "," in text else text
    tokens = cleaned.split()
    if not tokens:
        raise ValueError("no numbers given")
    return [int(token) for token in tokens]


def spread(numbers):
    """Distance between the largest and smallest values."""
    return find_max(numbers) - find_min(numbers)


def max_positions(numbers):
    """All indices at which the maximum value occurs."""
    top = find_max(numbers)
    return [index for index, value in enumerate(numbers) if value == top]


def describe(numbers):
    """Build a one-line report about the maximum of a list of integers."""
    top = find_max(numbers)
    positions = max_positions(numbers)
    where = "index {0}".format(positions[0]) if len(positions) == 1 else "indices {0}".format(positions)
    sign = "negative" if top < 0 else "non-negative"
    count_note = "single value" if len(numbers) == 1 else "{0} values".format(len(numbers))
    return "max {0} ({1}) at {2}; {3}, spread {4}".format(top, sign, where, count_note, spread(numbers))


def running_maxima(numbers):
    """Return the running maximum after each element."""
    result = [numbers[0]]
    for value in numbers[1:]:
        result.append(max(value, result[-1]))
    return result


def main():
    samples = ["10 5 20 8", "7", "-4, -9, -2, -30", "3 3 1 3"]
    for raw in samples:
        numbers = parse_numbers(raw)
        print(describe(numbers))
        history = running_maxima(numbers)
        trend = "flat" if history[0] == history[-1] else "rising"
        print("  running: {0} ({1})".format(history, trend))

    overall = find_max([find_max(parse_numbers(raw)) for raw in samples])
    verdict = "all maxima are small" if overall < 100 else "large maximum present"
    print("overall max {0}: {1}".format(overall, verdict))


if __name__ == "__main__":
    main()

