import sys


def _key(item):
    """Return a hashable key for item, falling back to a typed repr."""
    try:
        hash(item)
    except TypeError:
        return ('repr', type(item).__name__, repr(item))
    return ('hash', type(item).__name__, item)


def remove_duplicates(items):
    """Return a new list without duplicates, keeping first occurrences."""
    source = items if isinstance(items, list) else list(items)
    seen = set()
    result = []
    for item in source:
        key = _key(item)
        if key not in seen:
            seen.add(key)
            result.append(item)
    return result


def duplicate_counts(items):
    """Map each distinct element's key to how many times it appeared."""
    counts = {}
    for item in items:
        key = _key(item)
        counts[key] = counts[key] + 1 if key in counts else 1
    return counts


def duplicates_only(items):
    """Return the elements (first occurrence order) that repeat."""
    counts = duplicate_counts(items)
    return [item for item in remove_duplicates(items) if counts[_key(item)] > 1]


def describe(item):
    """Short, readable rendering of a single element."""
    text = item if isinstance(item, str) else repr(item)
    shortened = text[:17] + '...' if len(text) > 20 else text
    return shortened


def report(items):
    """Build a multi-line summary of the de-duplication of items."""
    unique = remove_duplicates(items)
    removed = len(items) - len(unique)
    repeats = duplicates_only(items)
    noun = 'element' if removed == 1 else 'elements'
    lines = ["input : [%s]" % ', '.join(describe(i) for i in items),
             "unique: [%s]" % ', '.join(describe(i) for i in unique),
             "removed %d duplicate %s" % (removed, noun)]
    detail = ', '.join(describe(i) for i in repeats) if repeats else 'none'
    lines.append("repeated values: " + detail)
    ratio = len(unique) / len(items) if items else 1.0
    lines.append("uniqueness: %.0f%%" % (ratio * 100))
    return '\n'.join(lines)


