def celsius_to_fahrenheit(celsius):
    """Convert a Celsius temperature to Fahrenheit."""
    value = parse_temperature(celsius)
    return value * 9 / 5 + 32


def parse_temperature(value):
    """Accept a number or a numeric string and return it as a float."""
    text = value.strip() if isinstance(value, str) else value
    if isinstance(text, bool):
        raise TypeError("temperature must be a number, not a boolean")
    if isinstance(text, str):
        cleaned = text[:-1] if text.endswith(("C", "c")) else text
        try:
            return float(cleaned)
        except ValueError:
            raise ValueError("could not read a temperature from %r" % value)
    if isinstance(text, (int, float)):
        return float(text)
    raise TypeError("unsupported temperature type: %s" % type(value).__name__)


def describe(celsius):
    """Return a short description of what the Celsius reading means."""
    c = parse_temperature(celsius)
    if c <= 0:
        return "freezing" if c == 0 else "below freezing"
    if c >= 100:
        return "boiling" if c == 100 else "above boiling"
    if c < 15:
        return "cold"
    return "mild" if c < 28 else "hot"


def format_conversion(celsius, decimals=1):
    """Format one conversion as a single readable line."""
    c = parse_temperature(celsius)
    f = celsius_to_fahrenheit(c)
    width = 2 if decimals < 2 else decimals
    left = "{:>8.{p}f} C".format(c, p=decimals)
    right = "{:>8.{p}f} F".format(f, p=width)
    return "{} = {}  ({})".format(left, right, describe(c))


def conversion_table(readings, decimals=1):
    """Build a report for several readings, skipping unreadable ones."""
    lines = []
    bad = 0
    for reading in readings:
        try:
            lines.append(format_conversion(reading, decimals))
        except (TypeError, ValueError) as exc:
            bad += 1
            lines.append("  skipped {!r}: {}".format(reading, exc))
    summary = "all {} readings converted".format(len(lines)) if bad == 0 else \
        "{} of {} readings failed".format(bad, len(readings))
    lines.append(summary)
    return "\n".join(lines)


def main(argv=None):
    import sys
    args = sys.argv[1:] if argv is None else list(argv)
    readings = args if args else [-40, 0, "25", 36.6, 100, "120c", "warm"]
    decimals = 0 if len(readings) > 12 else 1
    print(conversion_table(readings, decimals))
    usable = [parse_temperature(r) for r in readings if _is_readable(r)]
    if not usable:
        print("no usable readings")
        return 1
    print("hottest: {:.1f} F".format(celsius_to_fahrenheit(max(usable))))
    return 0


def _is_readable(value):
    try:
        parse_temperature(value)
    except (TypeError, ValueError):
        return False
    return True


if __name__ == "__main__":
    raise SystemExit(main())

