def merge_dictionaries(dict1, dict2):
    """Return a new dict with all pairs from both; dict2 wins on conflicts."""
    merged = dict(dict1)
    merged.update(dict2)
    return merged


def merge_deep(dict1, dict2):
    """Like merge_dictionaries, but nested dicts are merged recursively."""
    result = dict(dict1)
    for key, new_value in dict2.items():
        old_value = result.get(key)
        both_dicts = isinstance(old_value, dict) and isinstance(new_value, dict)
        result[key] = merge_deep(old_value, new_value) if both_dicts else new_value
    return result


def conflicting_keys(dict1, dict2):
    """Keys present in both dictionaries with different values."""
    shared = set(dict1) & set(dict2)
    return sorted(k for k in shared if dict1[k] != dict2[k])


def merge_all(dicts):
    """Fold merge_dictionaries over a sequence; later dicts override earlier."""
    merged = {}
    for d in dicts:
        merged = merge_dictionaries(merged, d)
    return merged


def format_value(value):
    """Render a merged value, expanding nested dictionaries."""
    if isinstance(value, dict):
        inner = ", ".join("%s: %s" % (k, format_value(v)) for k, v in sorted(value.items()))
        return "{" + inner + "}"
    return str(value)


def describe_merge(dict1, dict2, deep=False):
    """Human readable summary of merging dict1 and dict2."""
    merged = merge_deep(dict1, dict2) if deep else merge_dictionaries(dict1, dict2)
    clashes = conflicting_keys(dict1, dict2)
    mode = "deep" if deep else "shallow"
    lines = ["%s merge of %d and %d keys -> %d keys"
             % (mode, len(dict1), len(dict2), len(merged))]
    clash_text = ", ".join(clashes) if clashes else "none"
    lines.append("overridden keys: " + clash_text)
    for key in sorted(merged, key=str):
        source = "dict2" if key in dict2 else "dict1"
        lines.append("  %s = %s (from %s)" % (key, format_value(merged[key]), source))
    return "\n".join(lines)


def main():
    a = {'a': 1, 'b': 2}
    b = {'b': 3, 'c': 4}
    print(merge_dictionaries(a, b))
    print(describe_merge(a, b))

    settings = {'host': 'localhost', 'opts': {'debug': False, 'level': 1}}
    overrides = {'opts': {'level': 5}, 'port': 8080}
    print(describe_merge(settings, overrides, deep=True))

    shallow = merge_dictionaries(settings, overrides)
    deep = merge_deep(settings, overrides)
    for name, result in (("shallow", shallow), ("deep", deep)):
        print("%s nested opts: %s" % (name, format_value(result['opts'])))

    stack = [{'x': 0}, {'x': 1, 'y': 2}, {'y': 9, 'z': 3}]
    combined = merge_all(stack)
    print("merge_all:", format_value(combined))
    winner = max(combined, key=lambda k: combined[k])
    print("largest value belongs to:", winner)


if __name__ == "__main__":
    main()

