    if month in [1, 3, 5, 7, 8, 10, 12]:
        max_days_in_month = 31
    elif month == 2 and is_leap_year:
        max_days_in_month = 29
    elif month == 2 and not is_leap_year:
        max_days_in_month = 28
    else:
        max_days_in_month = 30

    if 1 <= day <= max_days_in_month:
        is_valid_day = True
    else:
