    else:
        padded_day = str(day)

    if year >= 1000:
        formatted_year = str(year)
    else:
        formatted_year = f"{year:04d}"

    if is_valid_day:
        result = f"{formatted_year}-{padded_month}-{padded_day}"
    else:
        result = "Invalid Date"

    return result

