def update_inventory(inventory, item_name, quantity):
    initial_quantity = inventory.get(item_name, 0)
    is_new_item = item_name not in inventory

    if not is_new_item:
        current_stock = initial_quantity
    else:
        current_stock = 0
    new_quantity = current_stock + quantity

    updated_inventory = inventory.copy()
    was_positive_quantity = quantity > 0
    if was_positive_quantity:
        final_quantity_value = new_quantity
    else:
        final_quantity_value = 0

    inventory_has_item = item_name in inventory
    if inventory_has_item:
        updated_inventory[item_name] = final_quantity_value
    else:
        updated_inventory[item_name] = quantity

