import re

HASHTAG_RE = re.compile(r'#(\w+)')


def extract_hashtags(text):
    """Return the hashtags found in text, without the leading '#'."""
    source = text if isinstance(text, str) else str(text)
    return HASHTAG_RE.findall(source)


def normalize_hashtags(text, casefold=True):
    """Return hashtags in a canonical form, preserving first-seen order."""
    tags = extract_hashtags(text)
    seen = []
    for tag in tags:
        candidate = tag.lower() if casefold else tag
        if candidate not in seen:
            seen.append(candidate)
    return seen


def count_hashtags(texts):
    """Count how often each normalized hashtag appears across several texts."""
    counts = {}
    for text in texts:
        for tag in normalize_hashtags(text):
            counts[tag] = counts[tag] + 1 if tag in counts else 1
    return counts


def rank_hashtags(counts, limit=None):
    """Sort hashtags by descending count, then alphabetically."""
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ordered if limit is None else ordered[:limit]


def describe(text):
    """Build a one-line description of the hashtags inside a single text."""
    tags = extract_hashtags(text)
    preview = text if len(text) <= 30 else text[:27] + '...'
    body = ', '.join('#' + tag for tag in tags) if tags else 'no hashtags'
    return '{!r} -> {}'.format(preview, body)


def format_report(texts, limit=3):
    """Render a small report about the hashtags used in a list of texts."""
    lines = [describe(text) for text in texts]
    counts = count_hashtags(texts)
    ranking = rank_hashtags(counts, limit)
    lines.append('')
    heading = 'Top {} hashtags:'.format(limit) if ranking else 'No hashtags at all.'
    lines.append(heading)
    for position, (tag, count) in enumerate(ranking, start=1):
        times = 'time' if count == 1 else 'times'
        lines.append('  {}. {} ({} {})'.format(position, tag, count, times))
    total = sum(counts.values())
    summary = '{} distinct tags, {} mentions'.format(len(counts), total) if total else 'nothing to summarize'
    lines.append(summary)
    return '\n'.join(lines)


def main():
    texts = [
        'This is a #test with #python.',
        'No hashtags here.',
        '#Python and #python are the same tag, but #Django is another one.',
        'Mixed: #test #test #data_science, and a lone # symbol.',
    ]
    print(extract_hashtags(texts[0]))
    print(extract_hashtags(texts[1]))
    print(format_report(texts))


if __name__ == '__main__':
    main()

