def parse_limit(raw):
    """Turn user supplied input into a plain integer limit."""
    candidate = raw.strip() if isinstance(raw, str) else raw
    if isinstance(candidate, bool):
        raise ValueError("a boolean is not a valid limit")
    try:
        return int(candidate)
    except (TypeError, ValueError):
        raise ValueError("cannot read a limit from " + repr(candidate))


def list_of_squares(n):
    """Return the squares of 1..n, or an empty list when n is not positive."""
    limit = n if n > 0 else 0
    return [i * i for i in range(1, limit + 1)]


def sum_of_squares(n):
    """Sum the squares of 1..n."""
    return sum(list_of_squares(n))


def average_square(squares):
    """Mean of the given squares (0.0 for an empty list)."""
    count = len(squares)
    mean = sum(squares) / count if count else 0.0
    return mean


def describe_squares(n, squares):
    """One-line summary of a computed list of squares."""
    label = "square" if len(squares) == 1 else "squares"
    largest = squares[-1] if squares else 0
    mean = average_square(squares)
    return "n={0}: {1} {2}, total {3}, largest {4}, mean {5:.2f}".format(
        n, len(squares), label, sum(squares), largest, mean
    )


def format_table(squares):
    """Render the squares as aligned lines showing each successive gap."""
    if not squares:
        return ["(no squares)"]
    value_width = len(str(squares[-1]))
    index_width = len(str(len(squares)))
    lines = []
    for index, value in enumerate(squares, 1):
        gap = value - squares[index - 2] if index > 1 else value
        lines.append(
            "{0:>{1}} -> {2:>{3}}  (+{4})".format(
                index, index_width, value, value_width, gap
            )
        )
    return lines


def report(raw):
    """Parse one input, compute its squares and return report lines."""
    try:
        n = parse_limit(raw)
    except ValueError as error:
        return ["skipping {0!r}: {1}".format(raw, error)]
    squares = list_of_squares(n)
    header = describe_squares(n, squares)
    body = format_table(squares)
    return [header] + ["    " + line for line in body]


def main():
    inputs = ["3", 0, "  5 ", -2, "abc", 1, None, "10"]
    for raw in inputs:
        for line in report(raw):
            print(line)
    biggest = max(parse_limit(raw) for raw in ("3", "5", "10"))
    print("largest requested limit: {0}".format(biggest))
    print("sum of squares up to {0}: {1}".format(biggest, sum_of_squares(biggest)))


if __name__ == "__main__":
    main()

