def normalize(s, case_sensitive=True):
    """Validate s and return the form used when comparing characters."""
    if not isinstance(s, str):
        raise TypeError("expected a string, got " + type(s).__name__)
    text = s if case_sensitive else s.casefold()
    return text


def pluralize(count, noun):
    """Format a count with its noun, adding a plural s when needed."""
    suffix = "" if count == 1 else "s"
    return "{0} {1}{2}".format(count, noun, suffix)


def has_unique_chars(s):
    """Return True if every character of s occurs exactly once."""
    text = normalize(s)
    seen = set()
    for ch in text:
        if ch in seen:
            return False
        seen.add(ch)
    return True


def first_duplicate(text):
    """Return the first character that repeats, or None when all are unique."""
    seen = set()
    for ch in text:
        if ch in seen:
            return ch
        seen.add(ch)
    return None


def duplicate_counts(text):
    """Map each repeated character to how many times it appears."""
    counts = {}
    for ch in text:
        counts[ch] = counts.get(ch, 0) + 1
    return {ch: n for ch, n in counts.items() if n > 1}


def longest_unique_prefix(text):
    """Length of the longest starting run of pairwise distinct characters."""
    seen = set()
    for index, ch in enumerate(text):
        if ch in seen:
            return index
        seen.add(ch)
    return len(text)


def describe(s, case_sensitive=True):
    """Build a one-line human readable verdict for the string s."""
    text = normalize(s, case_sensitive)
    mode = "case sensitive" if case_sensitive else "case insensitive"
    label = repr(s) if s else "the empty string"
    if has_unique_chars(text):
        amount = pluralize(len(text), "character")
        return "{0} [{1}]: all {2} are unique".format(label, mode, amount)
    culprit = first_duplicate(text)
    extra = sorted(ch for ch in duplicate_counts(text) if ch != culprit)
    listed = " ".join(repr(ch) for ch in extra)
    tail = ", also " + listed if extra else ""
    prefix = longest_unique_prefix(text)
    return "{0} [{1}]: repeats {2!r}{3}; unique prefix of length {4}".format(
        label, mode, culprit, tail, prefix
    )


def main():
    samples = ["abc", "abca", "", "aA", "hello world", "Python3"]
    for sample in samples:
        print(describe(sample))
        if has_unique_chars(sample) != has_unique_chars(sample.casefold()):
            print("  " + describe(sample, case_sensitive=False))
    good = sum(1 for sample in samples if has_unique_chars(sample))
    print("{0} of {1} unique".format(good, pluralize(len(samples), "sample")))


if __name__ == "__main__":
    main()

