import sys


def sum_digits(n):
    """Return the sum of the decimal digits of the non-negative integer n."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("sum_digits() requires an int")
    if n < 0:
        raise ValueError("sum_digits() requires a non-negative int")
    total = 0
    while n:
        n, digit = divmod(n, 10)
        total += digit
    return total


def digital_root(n):
    """Repeatedly sum the digits until a single digit remains."""
    result = n if n < 10 else digital_root(sum_digits(n))
    return result


def additive_persistence(n):
    """How many digit-sum steps are needed to reach a single digit."""
    steps = 0 if n < 10 else 1 + additive_persistence(sum_digits(n))
    return steps


def is_harshad(n):
    """True when n is divisible by its own digit sum."""
    divisor = sum_digits(n)
    divisible = False if divisor == 0 else n % divisor == 0
    return divisible


def parse_token(token):
    """Turn a textual number into an int, or None when it is not usable."""
    cleaned = token.strip().replace(",", "").replace("_", "")
    value = int(cleaned) if cleaned.isdigit() else None
    return value


def parse_numbers(tokens):
    values, rejected = [], []
    for token in tokens:
        value = parse_token(token)
        if value is None:
            rejected.append(token.strip())
        else:
            values.append(value)
    return values, rejected


def format_row(value, width):
    harshad = "yes" if is_harshad(value) else "no"
    return "{:>{w}}  {:>3}  {:>3}  {:>3}  {}".format(
        value, sum_digits(value), digital_root(value),
        additive_persistence(value), harshad, w=width)


def build_report(values):
    width = max(len(str(v)) for v in values) if values else 1
    lines = ["{:>{w}}  {:>3}  {:>3}  {:>3}  {}".format(
        "n", "sum", "dr", "ap", "harshad", w=width)]
    lines.extend(format_row(value, width) for value in values)
    return lines


def main(argv):
    tokens = argv[1:] if len(argv) > 1 else sys.stdin.read().split()
    values, rejected = parse_numbers(tokens)
    for line in build_report(values):
        print(line)
    if values:
        best = max(values, key=sum_digits)
        noun = "number" if len(values) == 1 else "numbers"
        print("{} {} scanned; largest digit sum is {} (from {})".format(
            len(values), noun, sum_digits(best), best))
    for token in rejected:
        print("skipped: {}".format(token))
    status = 1 if rejected else 0
    return status


if __name__ == "__main__":
    sys.exit(main(sys.argv))

