def validate_size(n):
    """Return a sane table size, raising for inputs that make no sense."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("table size must be an integer, got %r" % (n,))
    size = n if n >= 0 else 0
    if size > 50:
        raise ValueError("table size %d is too large to display" % size)
    return size


def build_table(n):
    """Build the n x n multiplication table as a list of rows."""
    return [[row * col for col in range(1, n + 1)] for row in range(1, n + 1)]


def column_width(table):
    """Width needed for the widest entry of a non-empty table."""
    largest = max(max(row) for row in table)
    return len(str(largest))


def format_row(row, width, label=None):
    """Render one row, optionally prefixed by a header label."""
    cells = " ".join(str(value).rjust(width) for value in row)
    prefix = str(label).rjust(width) + " |" if label is not None else " " * (width + 2)
    return prefix + " " + cells


def format_table(table, header=True):
    """Render the whole table as a list of text lines."""
    if not table:
        return []
    width = column_width(table)
    lines = []
    if header:
        lines.append(format_row(range(1, len(table) + 1), width, label="x"))
        lines.append("-" * len(lines[0]))
    for index, row in enumerate(table, start=1):
        label = index if header else None
        lines.append(format_row(row, width, label))
    return lines


def multiplication_table(n):
    """Print the multiplication table up to n x n and return it as lists."""
    size = validate_size(n)
    table = build_table(size)
    for line in format_table(table):
        print(line)
    if not table:
        print("(empty table)")
    return table


def describe(table):
    """One-line summary of a generated table."""
    size = len(table)
    shape = "%dx%d" % (size, size) if size else "empty"
    total = sum(sum(row) for row in table)
    plural = "entries" if size != 1 else "entry"
    return "%s table, %d %s, sum = %d" % (shape, size * size, plural, total)


def main():
    for requested in (2, 5, 0, 12):
        heading = "table for n = %d" % requested if requested else "degenerate case"
        print(heading)
        table = multiplication_table(requested)
        print(describe(table))
        print()
    for candidate in ("4", 99, -3):
        try:
            multiplication_table(candidate)
        except (TypeError, ValueError) as error:
            print("rejected %r: %s" % (candidate, error))
        else:
            print("accepted %r" % (candidate,))


if __name__ == "__main__":
    main()

