BEATS = {'rock': 'scissors', 'paper': 'rock', 'scissors': 'paper'}


def normalize(choice):
    """Turn a user-supplied choice into a canonical move name."""
    text = choice.strip().lower() if isinstance(choice, str) else str(choice).lower()
    shorthand = {'r': 'rock', 'p': 'paper', 's': 'scissors'}
    return shorthand[text] if text in shorthand else text


def rock_paper_scissors(player1_choice, player2_choice):
    first = normalize(player1_choice)
    second = normalize(player2_choice)
    for label, move in (('player1_choice', first), ('player2_choice', second)):
        if move not in BEATS:
            raise ValueError("invalid %s: %r" % (label, move))
    if first == second:
        return "It's a tie!"
    return 'Player 1 wins!' if BEATS[first] == second else 'Player 2 wins!'


def score_round(player1_choice, player2_choice):
    """Return (p1_points, p2_points) for one round."""
    result = rock_paper_scissors(player1_choice, player2_choice)
    if result == "It's a tie!":
        return (1, 1)
    return (3, 0) if result == 'Player 1 wins!' else (0, 3)


def describe_round(player1_choice, player2_choice):
    first = normalize(player1_choice)
    second = normalize(player2_choice)
    result = rock_paper_scissors(first, second)
    if first == second:
        reason = 'both played %s' % first
    else:
        winner = first if BEATS[first] == second else second
        loser = second if winner == first else first
        reason = '%s beats %s' % (winner, loser)
    return '%s vs %s -> %s (%s)' % (first, second, result, reason)


def play_match(rounds):
    """Play a sequence of (p1, p2) choices and report the outcome."""
    total1 = total2 = 0
    lines = []
    for index, (p1, p2) in enumerate(rounds, start=1):
        lines.append('Round %d: %s' % (index, describe_round(p1, p2)))
        gained1, gained2 = score_round(p1, p2)
        total1 += gained1
        total2 += gained2
    if total1 == total2:
        summary = 'Match drawn %d-%d' % (total1, total2)
    else:
        leader = 'Player 1' if total1 > total2 else 'Player 2'
        high = total1 if total1 > total2 else total2
        low = total2 if total1 > total2 else total1
        summary = 'Match won by %s %d-%d' % (leader, high, low)
    lines.append(summary)
    return lines


def main():
    rounds = [('rock', 'scissors'), ('paper', 'rock'), ('s', 'S'),
              ('Rock', 'paper'), ('scissors', 'p')]
    for line in play_match(rounds):
        print(line)
    try:
        rock_paper_scissors('rock', 'lizard')
    except ValueError as exc:
        print('Rejected: %s' % exc)


if __name__ == '__main__':
    main()

