def portfolio_value(stocks, prices):
    total_value = 0

    for ticker, quantity in stocks.items():
        if ticker in prices:
            price = prices[ticker]
        else:
            price = 0
        stock_value = quantity * price
        total_value += stock_value

    if total_value > 0:
        final_value = total_value
    else:
        final_value = 0

    return final_value

def calculate_portfolio_status(stocks, prices):
    value = portfolio_value(stocks, prices)
    if not stocks:
        is_empty = True
    else:
        is_empty = False
    if is_empty:
        status_message = "Portfolio is empty."
    else:
        status_message = f"Portfolio value: ${value}"

    return status_message

def get_risk_level(stocks, prices):
    value = portfolio_value(stocks, prices)
    if value > 10000:
        risk = "High"
    else:
        if value > 1000:
            risk = "Low"
        else:
            risk = "Very Low"

    return risk

def get_formatted_value(stocks, prices):
    value = portfolio_value(stocks, prices)
    if value % 1 != 0:
        formatted = f"${value:.2f}"
    else:
        formatted = f"${int(value)}"

    return formatted

def check_for_missing_prices(stocks, prices):
    missing_tickers = [ticker for ticker in stocks if ticker not in prices]
    if missing_tickers:
        has_missing = True
    else:
        has_missing = False
    if not has_missing:
        message = "All prices available."
    else:
        message = f"Missing prices for: {', '.join(missing_tickers)}"

    return message

