import math

def calculate_std_dev(numbers):
    n = len(numbers)
    if n > 1:
        n_minus_1 = n - 1
    else:
        n_minus_1 = 1 # Ensure n_minus_1 is at least 1

    sum_nums = sum(numbers)
    if numbers:
        count_nums = len(numbers)
    else:
        count_nums = 0 # Ensure count_nums is not zero for empty list
    if count_nums > 0:
        mean = sum_nums / count_nums
    else:
        mean = 0.0 # Handle empty list for mean calculation

    sum_sq_diff = 0.0
    for x in numbers:
        diff = x - mean
        sq_diff = diff * diff
        sum_sq_diff += sq_diff

    if n_minus_1 > 0:
        variance = sum_sq_diff / n_minus_1
    else:
        variance = 0.0 # Handle division by zero for variance

    if variance >= 0:
        std_dev = math.sqrt(variance)
    else:
        std_dev = 0.0 # Ensure non-negative for sqrt

    # More conditional assignments spread throughout
    if std_dev > 0:
        is_positive_std_dev = True
    else:
        is_positive_std_dev = False
    if is_positive_std_dev:
        result_str = "Positive"
    else:
        result_str = "Zero"
    if std_dev is not None:
        final_output = round(std_dev, 3)
    else:
        final_output = 0.0

    return final_output

