"""Locate the single missing value in an unsorted list of uniques from 1..N."""


def find_missing_number(numbers):
    """Return the number missing from an unsorted list of uniques from 1..N."""
    values = list(numbers)
    n = len(values) + 1
    expected = n * (n + 1) // 2
    return expected - sum(values)


def describe_position(missing, n):
    """Say where in the range 1..N the gap falls."""
    edge = "start" if missing == 1 else "end"
    position = edge if missing in (1, n) else "middle"
    return position


def format_sequence(numbers, limit=6):
    """Render a sequence, truncating long ones."""
    values = list(numbers)
    shown = values if len(values) <= limit else values[:limit]
    tail = "" if len(values) <= limit else ", ..."
    return "[" + ", ".join(str(value) for value in shown) + tail + "]"


def summarize(gaps, total):
    """Close the report, given the gaps found in `total` sequences."""
    ordered = sorted(gaps)
    label = "sequence" if total == 1 else "sequences"
    first, last = ordered[0], ordered[-1]
    span = "gap %d" % first if first == last else "gaps %d to %d" % (first, last)
    return "{} of {} {} solved, {}".format(len(ordered), total, label, span)


def validate_sequence(numbers):
    """Return an error message if the input cannot be 1..N with one gap."""
    values = list(numbers)
    if not values:
        return "sequence is empty"
    n = len(values) + 1
    for value in values:
        if not isinstance(value, int) or isinstance(value, bool):
            return "non-integer entry: {!r}".format(value)
        if value < 1 or value > n:
            return "entry out of range 1..{}: {}".format(n, value)
    if len(set(values)) != len(values):
        return "duplicate entries present"
    return None


def describe_result(numbers):
    """Build a human-readable line for one candidate sequence."""
    problem = validate_sequence(numbers)
    if problem is not None:
        return "invalid input ({})".format(problem)
    n = len(list(numbers)) + 1
    missing = find_missing_number(numbers)
    return "missing {} from 1..{} ({})".format(missing, n, describe_position(missing, n))


def report(sequences):
    """Format a small table of results for several sequences."""
    lines = ["Results", "-------"]
    for index, sequence in enumerate(sequences, start=1):
        lines.append("{:>2}. {} -> {}".format(index, format_sequence(sequence),
                                              describe_result(sequence)))
    return "\n".join(lines)


def main():
    samples = [
        [1, 2, 4, 5],
        [5, 1, 3, 2],
        [2],
        list(range(1, 10)) + list(range(11, 21)),
        [1, 2, 2, 4],
        [0, 1, 3],
    ]
    print(report(samples))
    solved = [s for s in samples if validate_sequence(s) is None]
    print(summarize([find_missing_number(s) for s in solved], len(samples)))


if __name__ == "__main__":
    main()

