from collections import Counter


def normalize(text, letters_only=False):
    """Lower-case a string and drop the characters that must be ignored."""
    source = text if isinstance(text, str) else str(text)
    keep = str.isalnum if letters_only else (lambda ch: not ch.isspace())
    return "".join(ch for ch in source.lower() if keep(ch))


def signature(text, letters_only=False):
    """A canonical form shared by all anagrams of *text*."""
    return "".join(sorted(normalize(text, letters_only)))


def is_anagram(s1, s2):
    """True when s1 and s2 use the same letters with the same frequencies."""
    return Counter(normalize(s1)) == Counter(normalize(s2))


def difference(s1, s2):
    """Letters that keep s1 and s2 from being anagrams, as a sorted list."""
    a = Counter(normalize(s1))
    b = Counter(normalize(s2))
    extra = (a - b) + (b - a)
    return sorted(extra.elements())


def find_anagrams(word, candidates):
    """Every candidate that is an anagram of *word* but not the word itself."""
    key = signature(word, letters_only=True)
    own = normalize(word, letters_only=True)
    return [c for c in candidates
            if signature(c, letters_only=True) == key
            and normalize(c, letters_only=True) != own]


def group_anagrams(words):
    """Map each signature to the words sharing it, keeping insertion order."""
    groups = {}
    for word in words:
        key = signature(word, letters_only=True)
        bucket = groups[key] if key in groups else []
        bucket.append(word)
        groups[key] = bucket
    return groups


def describe(s1, s2):
    """One readable line comparing two strings."""
    verdict = "are anagrams" if is_anagram(s1, s2) else "are not anagrams"
    odd = difference(s1, s2)
    detail = "" if not odd else " (unmatched: %s)" % ", ".join(odd)
    return "%-14r %-14r %s%s" % (s1, s2, verdict, detail)


def main():
    pairs = [
        ("listen", "silent"),
        ("hello", "world"),
        ("Dormitory", "Dirty Room"),
        ("conversation", "voices rant on"),
        ("apple", "pale"),
    ]
    for left, right in pairs:
        print(describe(left, right))

    matches = sum(1 for left, right in pairs if is_anagram(left, right))
    label = "pair" if matches == 1 else "pairs"
    print("\n%d %s matched." % (matches, label))

    words = ["stop", "tops", "pots", "opt", "post", "spot", "top"]
    print("Anagrams of 'stop':", find_anagrams("stop", words))
    for key, bucket in group_anagrams(words).items():
        kind = "family" if len(bucket) > 1 else "lone word"
        print("  %s -> %s [%s]" % (key, ", ".join(bucket), kind))


if __name__ == "__main__":
    main()

