def normalize(sentence):
    """Collapse runs of whitespace, dropping leading/trailing blanks."""
    text = sentence if isinstance(sentence, str) else str(sentence)
    return " ".join(text.split())


def reverse_words(sentence):
    """Reverse the order of the words in a sentence, keeping words intact."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a str")
    words = normalize(sentence).split(" ")
    reversed_sentence = "" if words == [""] else " ".join(reversed(words))
    return reversed_sentence


def word_count(sentence):
    """Number of words in the sentence."""
    cleaned = normalize(sentence)
    return 0 if not cleaned else cleaned.count(" ") + 1


def is_palindromic_order(sentence):
    """True when reversing the word order leaves the sentence unchanged."""
    cleaned = normalize(sentence)
    return cleaned == reverse_words(cleaned)


def preserve_capitalization(sentence):
    """Reverse the words, then move sentence-initial capitalization along."""
    result = reverse_words(sentence)
    if not result:
        return result
    words = result.split(" ")
    original = normalize(sentence).split(" ")
    head = words[0].capitalize() if original[0][:1].isupper() else words[0]
    tail = words[1:]
    if tail:
        last = tail[-1]
        tail[-1] = last.lower() if last.istitle() and len(last) > 1 else last
    return " ".join([head] + tail)


def describe(sentence):
    """Build a one-line report about a sentence and its reversal."""
    count = word_count(sentence)
    noun = "word" if count == 1 else "words"
    flipped = reverse_words(sentence)
    shown = flipped if flipped else "(empty)"
    symmetry = "symmetric" if is_palindromic_order(sentence) else "asymmetric"
    return "{:>2} {:<5} | {:<24} | {}".format(count, noun, shown, symmetry)


def main():
    samples = [
        "hello world",
        "Python is fun",
        "   spaced   out   text  ",
        "solo",
        "one two one",
        "",
    ]
    print("input".ljust(26), "report")
    for sample in samples:
        label = repr(sample) if sample.strip() != sample else sample
        print(label.ljust(26), describe(sample))

    print()
    for sample in ("Python is fun", "The quick brown Fox"):
        print(sample, "->", preserve_capitalization(sample))

    assert reverse_words("hello world") == "world hello"
    assert reverse_words("Python is fun") == "fun is Python"


if __name__ == "__main__":
    main()

