def count_uppercase(text):
    """Return the number of uppercase letters in text."""
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    return sum(1 for ch in text if ch.isupper())


def count_lowercase(text):
    """Return the number of lowercase letters in text."""
    return sum(1 for ch in text if ch.islower())


def uppercase_ratio(text):
    """Fraction of the letters in text that are uppercase (0.0 for no letters)."""
    upper = count_uppercase(text)
    letters = upper + count_lowercase(text)
    return upper / letters if letters else 0.0


def classify(text):
    """Describe the capitalisation style of a piece of text."""
    ratio = uppercase_ratio(text)
    if ratio == 0.0:
        return "no uppercase"
    style = "all caps" if ratio == 1.0 else "mixed case"
    return style if ratio > 0.5 else "mostly lowercase"


def uppercase_positions(text):
    """Indexes at which uppercase letters occur."""
    return [i for i, ch in enumerate(text) if ch.isupper()]


def normalize(text):
    """Trim the text and collapse a missing value into an empty string."""
    return text.strip() if text is not None else ""


def describe(text):
    """Build a one-line report about the uppercase letters in text."""
    clean = normalize(text)
    total = count_uppercase(clean)
    noun = "letter" if total == 1 else "letters"
    positions = uppercase_positions(clean)
    where = ", ".join(str(p) for p in positions) if positions else "nowhere"
    shown = clean if len(clean) <= 24 else clean[:21] + "..."
    return "{!r}: {} uppercase {} at {} ({})".format(
        shown, total, noun, where, classify(clean)
    )


def summarize(samples):
    """Return the report lines for several samples plus a grand total."""
    lines = [describe(sample) for sample in samples]
    grand = sum(count_uppercase(normalize(s)) for s in samples)
    busiest = max(samples, key=lambda s: count_uppercase(normalize(s))) if samples else ""
    tail = "busiest sample: {!r}".format(normalize(busiest)) if grand else "nothing to report"
    lines.append("total uppercase letters: {} -- {}".format(grand, tail))
    return lines


def main():
    samples = [
        "Hello World",
        "python is fun",
        "HTTP",
        "  Trailing And Leading  ",
        None,
        "A very long sentence With Some Capitals in it",
    ]
    for line in summarize(samples):
        print(line)


if __name__ == "__main__":
    main()

