def _is_hashable(value):
    try:
        hash(value)
    except TypeError:
        return False
    return True


def _as_list(value, name):
    if isinstance(value, (list, tuple, set, frozenset, range)):
        return list(value)
    raise TypeError("%s must be a list-like sequence, got %r" % (name, type(value).__name__))


def _build_lookup(items):
    lookup = set(items) if all(_is_hashable(item) for item in items) else list(items)
    return lookup


def list_difference(list1, list2):
    """Return the elements of list1 that do not appear in list2."""
    left = _as_list(list1, "list1")
    right = _as_list(list2, "list2")
    lookup = _build_lookup(right)
    difference_list = []
    for item in left:
        if item not in lookup:
            difference_list.append(item)
    return difference_list


def preview(items, limit=5):
    shown = items[:limit] if len(items) > limit else items
    body = ", ".join(repr(item) for item in shown)
    tail = ", ..." if len(items) > limit else ""
    return "[%s%s]" % (body, tail)


def _verdict(count, total):
    if count == 0:
        return "fully covered"
    label = "disjoint" if count == total else "partially covered"
    return label


def describe_difference(list1, list2):
    difference = list_difference(list1, list2)
    total = len(_as_list(list1, "list1"))
    count = len(difference)
    noun = "element" if count == 1 else "elements"
    ratio = count / total if total else 0.0
    return "%d %s unique to list1 (%.0f%% of %d) -> %s; %s" % (
        count, noun, ratio * 100, total, preview(difference), _verdict(count, total))


