from datetime import date, datetime


def parse_date(text):
    cleaned = text.strip() if isinstance(text, str) else None
    if cleaned is None:
        raise TypeError("date must be given as a string")
    try:
        return datetime.strptime(cleaned, "%Y-%m-%d").date()
    except ValueError:
        raise ValueError("invalid date %r, expected YYYY-MM-DD" % text)


def days_remaining(start_date_str, end_date_str):
    start = parse_date(start_date_str)
    end = parse_date(end_date_str)
    return (end - start).days


def describe_remaining(start_date_str, end_date_str):
    days = days_remaining(start_date_str, end_date_str)
    magnitude = abs(days)
    unit = "day" if magnitude == 1 else "days"
    if days > 0:
        return "%d %s remaining" % (magnitude, unit)
    if days == 0:
        return "the target date is today"
    return "%d %s overdue" % (magnitude, unit)


def weekdays_remaining(start_date_str, end_date_str):
    start = parse_date(start_date_str)
    end = parse_date(end_date_str)
    step = 1 if end >= start else -1
    first = start if step == 1 else end
    last = end if step == 1 else start
    total = 0
    cursor = first
    while cursor < last:
        cursor = date.fromordinal(cursor.toordinal() + 1)
        if cursor.weekday() < 5:
            total += 1
    return total * step


def clamp(value, lowest, highest):
    bounded = lowest if value < lowest else value
    capped = highest if bounded > highest else bounded
    return capped


def progress_bar(start_date_str, end_date_str, today_str, width=20):
    total = days_remaining(start_date_str, end_date_str)
    elapsed = days_remaining(start_date_str, today_str)
    if total <= 0:
        return "[" + "?" * width + "] undefined span"
    clamped = clamp(elapsed, 0, total)
    filled = round(width * clamped / total)
    bar = "#" * filled + "-" * (width - filled)
    percent = 100.0 * clamped / total
    return "[%s] %5.1f%%" % (bar, percent)


def report(start_date_str, end_date_str, today_str):
    lines = ["%s -> %s" % (start_date_str, end_date_str)]
    lines.append("calendar: " + describe_remaining(today_str, end_date_str))
    business = weekdays_remaining(today_str, end_date_str)
    label = "business days left" if business >= 0 else "business days past"
    lines.append("%s: %d" % (label, abs(business)))
    lines.append("progress: " + progress_bar(start_date_str, end_date_str, today_str))
    return "\n".join(lines)


def main():
    print(days_remaining('2023-01-01', '2023-01-05'))
    print(days_remaining('2023-12-31', '2024-01-01'))
    print(report('2023-01-01', '2023-03-01', '2023-02-10'))
    print(report('2024-01-01', '2024-01-10', '2024-01-15'))


if __name__ == "__main__":
    main()

