            base_code = ord('a')
            shifted_code = char_code - effective_shift

            if shifted_code >= base_code:
                wrapped_code = shifted_code
            else:
                wrapped_code = shifted_code + alphabet_size
            decrypted_char = chr(wrapped_code)

            decrypted_chars.append(decrypted_char)
        else:
            decrypted_chars.append(char)

    result = "".join(decrypted_chars)
    if len(result) > 0:
        final_output = result
    else:
        final_output = ""
    return final_output

