def simulate_stack(stack, operation, item=None):
    """Perform a single 'push' or 'pop' on stack; return the stack or popped item."""
    op = operation.lower().strip() if isinstance(operation, str) else operation
    if op not in ('push', 'pop'):
        raise ValueError("operation must be 'push' or 'pop', got %r" % (operation,))
    if op == 'push':
        stack.append(item)
        return stack
    return stack.pop() if stack else None


def parse_command(text):
    """Turn a textual command like 'push 3' or 'pop' into an (operation, item) pair."""
    parts = text.split()
    if not parts:
        raise ValueError('empty command')
    operation = parts[0]
    raw = parts[1] if len(parts) > 1 else None
    item = _coerce(raw) if raw is not None else None
    return operation, item


def _coerce(raw):
    """Interpret a command argument as int, float or plain string."""
    try:
        return int(raw)
    except ValueError:
        pass
    try:
        return float(raw)
    except ValueError:
        return raw


def describe(operation, item, result, stack):
    """Build a one-line report of what an operation did."""
    op = operation.lower().strip()
    action = 'push %r' % (item,) if op == 'push' else 'pop'
    outcome = 'stack empty' if op == 'pop' and result is None else 'returned %r' % (result,)
    return '%-10s -> %-20s state=%r' % (action, outcome, stack)


def run_script(commands, stack=None):
    """Apply a sequence of textual commands, returning the final stack and a log."""
    working = stack if stack is not None else []
    log = []
    for text in commands:
        operation, item = parse_command(text)
        result = simulate_stack(working, operation, item)
        log.append(describe(operation, item, result, working))
    return working, log


def depth_summary(stack):
    """Short human-readable description of how full the stack is."""
    size = len(stack)
    noun = 'item' if size == 1 else 'items'
    label = 'empty' if size == 0 else '%d %s' % (size, noun)
    top = stack[-1] if stack else None
    tail = '' if top is None else ', top=%r' % (top,)
    return 'stack holds %s%s' % (label, tail)


def main():
    script = ['push 1', 'push 2', 'pop', 'push hello', 'push 4.5', 'pop', 'pop', 'pop']
    final, log = run_script(script)
    for line in log:
        print(line)
    print(depth_summary(final))


if __name__ == '__main__':
    main()

