def parse_limit(text):
    """Turn a textual limit into an int, raising ValueError on bad input."""
    cleaned = text.strip()
    body = cleaned[1:] if cleaned[:1] in ("+", "-") else cleaned
    if not body.isdigit():
        raise ValueError("not an integer limit: %r" % text)
    magnitude = int(body)
    value = -magnitude if cleaned.startswith("-") else magnitude
    return value


def cubes_up_to(limit):
    """Return the cubes of 0..limit inclusive; a negative limit yields []."""
    top = limit if limit >= 0 else -1
    cubes_list = [n ** 3 for n in range(top + 1)]
    return cubes_list


def column_width(cubes):
    """Width needed to right-align every cube in a table."""
    widest = max((len(str(c)) for c in cubes), default=1)
    width = widest if widest > 3 else 3
    return width


def format_cubes(cubes, per_row=5):
    """Render the cube list as right-aligned rows of at most per_row entries."""
    if not cubes:
        return "(no cubes)"
    width = column_width(cubes)
    rows = []
    for start in range(0, len(cubes), per_row):
        chunk = cubes[start:start + per_row]
        rows.append(" ".join(str(c).rjust(width) for c in chunk))
    return "\n".join(rows)


def summarize(limit, cubes):
    """One-line description of a cube list."""
    count = len(cubes)
    noun = "cube" if count == 1 else "cubes"
    total = sum(cubes)
    largest = cubes[-1] if cubes else None
    tail = "max %d" % largest if largest is not None else "nothing to cube"
    return "limit %d -> %d %s, sum %d, %s" % (limit, count, noun, total, tail)


def report(text):
    """Parse a limit given as text, build its cubes and describe them."""
    try:
        limit = parse_limit(text)
    except ValueError as exc:
        return "input %r rejected: %s" % (text, exc)
    cubes = cubes_up_to(limit)
    header = summarize(limit, cubes)
    shown = cubes if len(cubes) <= 20 else cubes[:20]
    body = format_cubes(shown)
    suffix = "\n  ..." if len(shown) < len(cubes) else ""
    return header + "\n" + body + suffix


def main():
    for text in ["3", "0", "1", "12", "-4", " +7 ", "seven"]:
        print(report(text))
        print("-" * 32)


if __name__ == "__main__":
    main()

