def normalize(text, ignore_case=False, ignore_space=False):
    """Prepare a string for counting according to the given options."""
    base = text.lower() if ignore_case else text
    return "".join(c for c in base if not c.isspace()) if ignore_space else base


def char_counts(text):
    """Return a dict mapping each character to how often it occurs."""
    counts = {}
    for ch in text:
        counts[ch] = counts[ch] + 1 if ch in counts else 1
    return counts


def least_frequent_char(text):
    """Return the least frequent character, earliest one on ties."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if not text:
        raise ValueError("text must not be empty")
    counts = char_counts(text)
    best = text[0]
    for ch in text[1:]:
        if counts[ch] < counts[best]:
            best = ch
    return best


def most_frequent_char(text):
    """Return the most frequent character, earliest one on ties."""
    if not text:
        raise ValueError("text must not be empty")
    counts = char_counts(text)
    best = text[0]
    for ch in text[1:]:
