def is_divisible_by_3_and_5(number):
    """Return True when number is divisible by both 3 and 5."""
    value = number if isinstance(number, int) and not isinstance(number, bool) else _coerce(number)
    return value % 3 == 0 and value % 5 == 0


def _coerce(raw):
    """Turn a textual or float-like input into an int, or raise a clear error."""
    if isinstance(raw, bool):
        return int(raw)
    if isinstance(raw, float):
        if raw != int(raw):
            raise ValueError("not an integer: %r" % (raw,))
        return int(raw)
    text = raw.strip() if isinstance(raw, str) else None
    if text is None:
        raise TypeError("unsupported input type: %s" % type(raw).__name__)
    body = text[1:] if text[:1] in ("+", "-") else text
    if not body.isdigit():
        raise ValueError("not an integer: %r" % (raw,))
    return int(text)


def classify(number):
    """Describe a number by its divisibility by 3 and 5."""
    value = number if isinstance(number, int) else _coerce(number)
    by_three = value % 3 == 0
    by_five = value % 5 == 0
    if by_three and by_five:
        return "both"
    if by_three:
        return "three"
    label = "five" if by_five else "neither"
    return label


def describe(number):
    """Human readable one-line verdict for a single input."""
    kind = classify(number)
    verdict = "divisible by 3 and 5" if kind == "both" else _partial_phrase(kind)
    return "%s: %s" % (number, verdict)


def _partial_phrase(kind):
    if kind == "neither":
        return "divisible by neither"
    divisor = 3 if kind == "three" else 5
    return "divisible by %d only" % divisor


def multiples_in(start, stop):
    """All values in [start, stop) divisible by both 3 and 5."""
    low = start if start <= stop else stop
    high = stop if start <= stop else start
    first = low + (-low) % 15
    return list(range(first, high, 15))


def report(values):
    """Build a report of per-value verdicts plus a summary count."""
    lines = [describe(v) for v in values]
    hits = sum(1 for v in values if is_divisible_by_3_and_5(v))
    noun = "value" if hits == 1 else "values"
    lines.append("%d %s divisible by 3 and 5" % (hits, noun))
    return "\n".join(lines)


def main():
    samples = [15, 10, "30", -45.0, 7]
    print(report(samples))
    window = multiples_in(1, 50)
    listing = ", ".join(str(n) for n in window) if window else "none"
    print("multiples of 15 below 50: %s" % listing)
    try:
        is_divisible_by_3_and_5("twelve")
    except ValueError as exc:
        print("rejected input -> %s" % exc)


if __name__ == "__main__":
    main()

