import random


def simulate_coin_flip():
    result = 'Heads' if random.random() < 0.5 else 'Tails'
    return result


def flip_many(count):
    n = count if count > 0 else 0
    return [simulate_coin_flip() for _ in range(n)]


def tally(flips):
    heads = sum(1 for flip in flips if flip == 'Heads')
    tails = len(flips) - heads
    return {'Heads': heads, 'Tails': tails}


def longest_streak(flips):
    best_face = flips[0] if flips else None
    best_len = 1 if flips else 0
    current_len = best_len
    for previous, current in zip(flips, flips[1:]):
        current_len = current_len + 1 if current == previous else 1
        if current_len > best_len:
            best_len = current_len
            best_face = current
    return best_face, best_len


def bias_label(counts):
    total = counts['Heads'] + counts['Tails']
    if total == 0:
        return 'no data'
    share = counts['Heads'] / total
    if abs(share - 0.5) <= 0.05:
        return 'balanced'
    return 'heads-leaning' if share > 0.5 else 'tails-leaning'


def format_percent(part, total):
    value = 100.0 * part / total if total else 0.0
    return '{:5.1f}%'.format(value)


def format_report(flips):
    counts = tally(flips)
    total = len(flips)
    face, streak = longest_streak(flips)
    lines = ['Coin flip report ({} flip{})'.format(total, '' if total == 1 else 's')]
    for name in ('Heads', 'Tails'):
        lines.append('  {:<5} {:4d}  {}'.format(name, counts[name], format_percent(counts[name], total)))
    streak_text = 'none' if face is None else '{} x {}'.format(streak, face)
    lines.append('  longest run: ' + streak_text)
    lines.append('  verdict: ' + bias_label(counts))
    return '\n'.join(lines)


def main(argv=None):
    args = argv if argv is not None else []
    raw = args[0] if args else '20'
    try:
        requested = int(raw)
    except ValueError:
        requested = 20
    flips = flip_many(requested)
    print('single flip:', simulate_coin_flip())
    print(format_report(flips))
    return 0 if flips else 1


if __name__ == '__main__':
    import sys
    raise SystemExit(main(sys.argv[1:]))

