    total = counts['Heads'] + counts['Tails']
    if total == 0:
        return 'no data'
    share = counts['Heads'] / total
    if abs(share - 0.5) <= 0.05:
        return 'balanced'
    return 'heads-leaning' if share > 0.5 else 'tails-leaning'


def format_percent(part, total):
    if total:
        value = 100.0 * part / total
    else:
        value = 0.0
    return '{:5.1f}%'.format(value)


def format_report(flips):
    counts = tally(flips)
    total = len(flips)
    face, streak = longest_streak(flips)
    lines = ['Coin flip report ({} flip{})'.format(total, '' if total == 1 else 's')]
    for name in ('Heads', 'Tails'):
        lines.append('  {:<5} {:4d}  {}'.format(name, counts[name], format_percent(counts[name], total)))
    if face is None:
        streak_text = 'none'
    else:
        streak_text = '{} x {}'.format(streak, face)
    lines.append('  longest run: ' + streak_text)
    lines.append('  verdict: ' + bias_label(counts))
    return '\n'.join(lines)


def main(argv=None):
    if argv is not None:
        args = argv
    else:
        args = []
    if args:
        raw = args[0]
    else:
        raw = '20'
    try:
        requested = int(raw)
    except ValueError:
        requested = 20
    flips = flip_many(requested)
    print('single flip:', simulate_coin_flip())
    print(format_report(flips))
    return 0 if flips else 1


if __name__ == '__main__':
