def dimensions(matrix):
    rows = len(matrix)
    cols = len(matrix[0]) if rows else 0
    return rows, cols


def format_value(value):
    text = str(int(value)) if isinstance(value, float) and value.is_integer() else str(value)
    return text


def format_matrix(matrix):
    rows, cols = dimensions(matrix)
    if rows == 0 or cols == 0:
        return "(empty matrix)"
    cells = [[format_value(value) for value in row] for row in matrix]
    widths = [max(len(row[c]) for row in cells) for c in range(cols)]
    lines = []
    for row in cells:
        padded = [text.rjust(widths[i]) for i, text in enumerate(row)]
        lines.append("[ " + "  ".join(padded) + " ]")
    return "\n".join(lines)


def validate(matrix, name):
    if not isinstance(matrix, list):
        raise TypeError(name + " must be a list of lists")
    rows, cols = dimensions(matrix)
    for index, row in enumerate(matrix):
        if not isinstance(row, list):
            raise TypeError("%s row %d must be a list" % (name, index))
        if len(row) != cols:
            raise ValueError("%s is ragged at row %d" % (name, index))
        for value in row:
            kind = "bool" if isinstance(value, bool) else type(value).__name__
            if kind not in ("int", "float"):
                raise TypeError("%s contains a non-numeric value: %r" % (name, value))
    return rows, cols


def matrix_subtract(matrix1, matrix2):
    rows1, cols1 = validate(matrix1, "matrix1")
    rows2, cols2 = validate(matrix2, "matrix2")
    if (rows1, cols1) != (rows2, cols2):
        raise ValueError("shape mismatch: %dx%d vs %dx%d" % (rows1, cols1, rows2, cols2))
    result_matrix = []
    for row1, row2 in zip(matrix1, matrix2):
        result_matrix.append([a - b for a, b in zip(row1, row2)])
    return result_matrix


def report(matrix1, matrix2):
    try:
        difference = matrix_subtract(matrix1, matrix2)
    except (TypeError, ValueError) as error:
        return "error: " + str(error)
    rows, cols = dimensions(difference)
    flat = [value for row in difference for value in row]
    nonzero = sum(1 for value in flat if value)
    peak = max(flat, key=abs) if flat else 0
    summary = "all zeros" if flat and not nonzero else "%d nonzero, peak %s" % (nonzero, format_value(peak))
    header = "difference (%dx%d, %s):" % (rows, cols, summary)
    return header + "\n" + format_matrix(difference)


def main():
    cases = [
        ([[1, 2], [3, 4]], [[1, 1], [1, 1]]),
        ([[5, 0]], [[1, -1]]),
        ([[2.5, 3.0], [1, 1]], [[0.5, 3.0], [1, 1]]),
        ([[1, 2, 3]], [[1, 2]]),
    ]
    for index, (first, second) in enumerate(cases, start=1):
        text = report(first, second)
        status = "failed" if text.startswith("error: ") else "ok"
        print("case %d (%s):" % (index, status))
        print(text)
        print()


if __name__ == "__main__":
    main()

