HEX_DIGITS = "0123456789ABCDEF"


def normalize(hex_string):
    """Strip whitespace, an optional sign and an optional 0x prefix."""
    text = hex_string.strip()
    sign = -1 if text.startswith("-") else 1
    body = text[1:] if text[0] in "+-" else text
    prefix = body[:2].lower()
    digits = body[2:] if prefix == "0x" else body
    return sign, digits.upper()


def digit_value(char):
    """Return the numeric value of a single hexadecimal digit."""
    position = HEX_DIGITS.find(char)
    if position < 0:
        raise ValueError("invalid hexadecimal digit: %r" % char)
    return position


def hex_to_decimal(hex_string):
    """Convert a hexadecimal string to its decimal integer value."""
    if not isinstance(hex_string, str):
        raise TypeError("hex_string must be a str")
    if not hex_string.strip():
        raise ValueError("hex_string must not be empty")
    sign, digits = normalize(hex_string)
    if not digits:
        raise ValueError("no hexadecimal digits found in %r" % hex_string)
    decimal_num = 0
    for char in digits:
        decimal_num = decimal_num * 16 + digit_value(char)
    return sign * decimal_num


def bit_width(value):
    """Number of bits needed to store the magnitude of value."""
    magnitude = -value if value < 0 else value
    return max(magnitude.bit_length(), 1)


def describe(hex_string):
    """Build a one-line report for a single conversion attempt."""
    try:
        value = hex_to_decimal(hex_string)
    except (TypeError, ValueError) as error:
        return "%-12s -> error: %s" % (repr(hex_string), error)
    parity = "even" if value % 2 == 0 else "odd"
    size = "fits in a byte" if -256 <= value < 256 else "%d bits" % bit_width(value)
    return "%-12s -> %d (%s, %s)" % (repr(hex_string), value, parity, size)


def checksum(hex_strings):
    """Sum the values of every string that converts successfully."""
    total = 0
    for item in hex_strings:
        try:
            total += hex_to_decimal(item)
        except (TypeError, ValueError):
            continue
    return total


def main():
    samples = ["FF", "A", "0x1f", "  deadBEEF ", "-2C", "0", "G7", ""]
    for sample in samples:
        print(describe(sample))
    total = checksum(samples)
    sign_label = "negative" if total < 0 else "non-negative"
    print("checksum: %d (%s, %d bits)" % (total, sign_label, bit_width(total)))


if __name__ == "__main__":
    main()

