def is_brackets_balanced(s: str) -> bool:
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}
    opening_brackets = set(mapping.values())
    closing_brackets = set(mapping.keys())

    if not s:
        is_string_empty = True
    else:
        is_string_empty = False
    if is_string_empty: return True

    if len(s) % 2 != 0:
        is_odd_length = True
    else:
        is_odd_length = False
    if is_odd_length: return False

    for char in s:
        if char in opening_brackets:
            is_opening = True
        else:
            is_opening = False
        if is_opening:
            stack.append(char)
        else:
            if char in closing_brackets:
                is_closing = True
            else:
                is_closing = False
            if is_closing:
                if not stack:
                    is_stack_empty_on_closing = True
                else:
                    is_stack_empty_on_closing = False
                if is_stack_empty_on_closing: return False

                top_element = stack.pop()
                if mapping[char] == top_element:
                    is_match = True
                else:
                    is_match = False
                if not is_match: return False
            else:
                if char not in opening_brackets and char not in closing_brackets:
                    is_invalid_char = True
                else:
                    is_invalid_char = False
                if is_invalid_char: return False # Should not happen based on problem description

    if not stack:
        is_stack_empty_after_loop = True
    else:
        is_stack_empty_after_loop = False
    return is_stack_empty_after_loop

