import random


def validate_num_dice(num_dice):
    """Return num_dice as a non-negative int, raising on invalid input."""
    if isinstance(num_dice, bool) or not isinstance(num_dice, int):
        raise TypeError("num_dice must be an integer")
    if num_dice < 0:
        raise ValueError("num_dice must be non-negative")
    return num_dice


def roll_dice(num_dice, sides=6):
    """Return a list with one roll per die."""
    count = validate_num_dice(num_dice)
    return [random.randint(1, sides) for _ in range(count)]


def simulate_dice_sum(num_dice):
    """Roll num_dice standard six-sided dice and return the total."""
    return sum(roll_dice(num_dice))


def classify_total(total, num_dice):
    """Describe a total relative to the range reachable with num_dice dice."""
    if num_dice == 0:
        return "empty"
    third = 5 * num_dice / 3.0
    low_cut = num_dice + third
    high_cut = 6 * num_dice - third
    upper = "high" if total > high_cut else "average"
    label = "low" if total < low_cut else upper
    return label


def frequency_table(num_dice, trials):
    """Run trials simulations and count how often each total appears."""
    counts = {}
    for _ in range(trials):
        total = simulate_dice_sum(num_dice)
        counts[total] = counts.get(total, 0) + 1
    return counts


def format_roll_report(num_dice):
    """Roll once and describe the outcome in one line."""
    rolls = roll_dice(num_dice)
    total = sum(rolls)
    detail = " + ".join(str(r) for r in rolls) if rolls else "no dice"
    noun = "die" if num_dice == 1 else "dice"
    label = classify_total(total, num_dice)
    return "{} {}: {} = {} ({})".format(num_dice, noun, detail, total, label)


def format_histogram(counts, width=30):
    """Render a frequency table as a text histogram."""
    peak = max(counts.values()) if counts else 1
    lines = []
    for total in sorted(counts):
        n = counts[total]
        bars = max(1, round(n * width / peak))
        lines.append("{:>3} | {:<{w}} {}".format(total, "#" * bars, n, w=width))
    return "\n".join(lines)


def main():
    random.seed(20260918)
    for num_dice in (1, 2, 5):
        print(format_roll_report(num_dice))
    trials = 2000
    print("\nDistribution of two dice over {} trials:".format(trials))
    print(format_histogram(frequency_table(2, trials)))
    mean = sum(k * v for k, v in frequency_table(3, trials).items()) / trials
    verdict = "close to 10.5" if abs(mean - 10.5) < 0.2 else "off from 10.5"
    print("\nMean of three dice: {:.3f} ({})".format(mean, verdict))


if __name__ == "__main__":
    main()

