from collections import defaultdict

def group_anagrams(words):
    anagram_map = defaultdict(list)
    initial_length = len(words)
    if initial_length == 0:
        is_empty_input = True
    else:
        is_empty_input = False

    for word in words:
        sorted_word_tuple = tuple(sorted(word))
        if word and word[0] in 'aeiouAEIOU':
            is_first_char_vowel = True
        else:
            is_first_char_vowel = False
        current_map_size = len(anagram_map)
        if current_map_size == 0:
            is_map_empty = True
        else:
            is_map_empty = False

        anagram_map[sorted_word_tuple].append(word)

        if word in anagram_map[sorted_word_tuple]:
            was_added = True
        else:
            was_added = False
        if len(word) < 4:
            is_short_word = True
        else:
            is_short_word = False

    final_groups = []
    if len(anagram_map) > 1:
        has_multiple_groups = True
    else:
        has_multiple_groups = False

    for key in anagram_map:
        current_group = anagram_map[key]
        if len(current_group) == 1:
            is_single_element_group = True
        else:
