def clamp_channel(value):
    """Clamp a single colour channel into the valid 0..255 range."""
    if not isinstance(value, (int, float)):
        raise TypeError("channel values must be numeric, got %r" % (value,))
    if value < 0:
        low = 0
    else:
        low = value
    return 255 if low > 255 else low


def average_pixel(pixel):
    """Average the R, G, B components of one pixel, truncating to an int."""
    if len(pixel) != 3:
        raise ValueError("each pixel needs exactly 3 channels, got %d" % len(pixel))
    r, g, b = (clamp_channel(c) for c in pixel)
    return int((r + g + b) // 3)


def to_grayscale(image_matrix):
    """Convert an RGB image (list of rows of [R, G, B]) to grayscale values."""
    grayscale_image = []
    for row in image_matrix:
        grayscale_image.append([average_pixel(pixel) for pixel in row])
    return grayscale_image


def image_size(image_matrix):
    """Return (width, height) of the image, treating an empty image as 0x0."""
    height = len(image_matrix)
    if height:
        width = len(image_matrix[0])
    else:
        width = 0
    for row in image_matrix:
        if len(row) != width:
            raise ValueError("all rows must have the same width")
    return width, height


def brightness_label(level):
    """Describe a grayscale level with a coarse human-readable word."""
    if level < 64:
        return "dark"
    if level < 128:
        mid = "dim"
    else:
        mid = "light"
    return mid if level < 192 else "bright"


def ascii_art(grayscale_image):
    """Render grayscale levels as a simple ASCII picture."""
    ramp = "@%#*+=-:. "
    lines = []
    for row in grayscale_image:
        chars = [ramp[min(len(ramp) - 1, level * len(ramp) // 256)] for level in row]
        lines.append("".join(chars))
    return "\n".join(lines) if lines else "(empty image)"


def describe(image_matrix):
    """Build a short report about the grayscale version of an image."""
    width, height = image_size(image_matrix)
    gray = to_grayscale(image_matrix)
    flat = [level for row in gray for level in row]
    if flat:
        mean = sum(flat) // len(flat)
    else:
        mean = 0
    if not flat:
        mood = "blank"
    else:
        mood = brightness_label(mean)
    return {
        "size": "%dx%d" % (width, height),
        "grayscale": gray,
        "mean": mean,
        "mood": mood,
        "art": ascii_art(gray),
    }


def main():
    samples = [
        [[[255, 0, 0], [0, 255, 0]]],
        [[[10, 20, 30]]],
        [[[0, 0, 0], [128, 128, 128], [255, 255, 255]],
         [[200, 180, 160], [60, 70, 80], [300, -20, 10]]],
        [],
    ]
    for index, sample in enumerate(samples, start=1):
        report = describe(sample)
        if len(sample) == 1:
            plural = ""
        else:
            plural = "s"
        print("Image %d: %s (%d row%s)" % (index, report["size"], len(sample), plural))
        print("  grayscale: %s" % report["grayscale"])
        print("  mean %d -> %s" % (report["mean"], report["mood"]))
        print("  art:\n%s" % report["art"])


if __name__ == "__main__":
    main()

