def parse_number(token):
    """Convert a single token into an int when it looks like a whole number."""
    text = token.strip()
    value = float(text)
    looks_integral = value.is_integer() and "." not in text and "e" not in text.lower()
    number = int(value) if looks_integral else value
    return number


def parse_numbers(text):
    """Read a whitespace or comma separated list of numbers."""
    tokens = [token for token in text.replace(",", " ").split() if token]
    return [parse_number(token) for token in tokens]


def format_number(value):
    """Render a parsed number without trailing float noise."""
    shown = str(value) if isinstance(value, int) else "{0:g}".format(value)
    return shown


def is_sorted(numbers):
    """Return True when numbers is in ascending (non-decreasing) order."""
    for previous, current in zip(numbers, numbers[1:]):
        if current < previous:
            return False
    return True


def first_descent(numbers):
    """Index of the first element smaller than its predecessor, or None."""
    for index in range(1, len(numbers)):
        if numbers[index] < numbers[index - 1]:
            return index
    return None


def order_label(numbers):
    """Describe the ordering more precisely than a plain boolean."""
    if not is_sorted(numbers):
        return "not ascending"
    has_equal = any(a == b for a, b in zip(numbers, numbers[1:]))
    label = "ascending with ties" if has_equal else "strictly ascending"
    return label


def describe(numbers):
    """Build a one line report about the ordering of numbers."""
    count = len(numbers)
    plural = "" if count == 1 else "s"
    listing = ", ".join(format_number(value) for value in numbers)
    shown = listing if listing else "(nothing)"
    header = "{0} value{1} [{2}]".format(count, plural, shown)
    if is_sorted(numbers):
        return "{0} -> True, {1}".format(header, order_label(numbers))
    index = first_descent(numbers)
    drop = "{0} follows {1}".format(
        format_number(numbers[index]), format_number(numbers[index - 1])
    )
    return "{0} -> False, breaks at index {1} ({2})".format(header, index, drop)


def main():
