        if is_sorted(numbers):
            sorted_count += 1
    total = len(samples)
    summary = "all" if sorted_count == total else "{0} of {1}".format(sorted_count, total)
    print("Ascending: {0} sample(s)".format(summary))


if __name__ == "__main__":
