def count_char(text, char_to_count):
    """Count how many times char_to_count appears in text."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if not isinstance(char_to_count, str):
        raise TypeError("char_to_count must be a string")
    if len(char_to_count) != 1:
        raise ValueError("char_to_count must be exactly one character")
    total = 0
    for ch in text:
        if ch == char_to_count:
            total += 1
    return total


def count_char_ignore_case(text, char_to_count):
    """Count occurrences of a character regardless of letter case."""
    folded = text.casefold() if isinstance(text, str) else text
    target = char_to_count.casefold() if isinstance(char_to_count, str) else char_to_count
    return count_char(folded, target)


def dominant_char(text):
    """Return the character with the highest count, or None for empty text."""
    best = None
    best_count = 0
    for ch in text:
        count = count_char(text, ch)
        if count > best_count:
            best, best_count = ch, count
    return best


def count_report(text, chars):
    """Build a mapping of each requested character to its count in text."""
    report = {}
    for ch in chars:
        report[ch] = count_char(text, ch) if len(ch) == 1 else None
    return report


def describe_count(text, char_to_count):
    """Render a human readable sentence about one character's frequency."""
    count = count_char(text, char_to_count)
    times = "time" if count == 1 else "times"
    shown = text if len(text) <= 20 else text[:17] + "..."
    verdict = "absent" if count == 0 else "present"
    return "{!r}: {!r} is {} ({} {})".format(shown, char_to_count, verdict, count, times)


def main():
    samples = [
        ("banana", "a"),
        ("Mississippi", "s"),
        ("Mississippi", "S"),
        ("", "x"),
    ]
    for text, ch in samples:
        print(describe_count(text, ch))
        exact = count_char(text, ch)
        loose = count_char_ignore_case(text, ch)
        note = "same ignoring case" if loose == exact else "ignoring case: {}".format(loose)
        print("   " + note)

    phrase = "counting characters carefully"
    top = dominant_char(phrase)
    label = top if top is not None else "(none)"
    print("Most frequent character in {!r}: {}".format(phrase, label))

    report = count_report(phrase, ["c", "e", "z", "ar"])
    for key in sorted(report):
        value = report[key]
        shown = "invalid key" if value is None else str(value)
        print("   {!r} -> {}".format(key, shown))


if __name__ == "__main__":
    main()

