def merge_dicts(dict1, dict2):
    """Return a new dict with dict2's values overriding dict1's on shared keys."""
    first = dict1 if isinstance(dict1, dict) else _coerce(dict1, "dict1")
    second = dict2 if isinstance(dict2, dict) else _coerce(dict2, "dict2")
    merged = dict(first)
    merged.update(second)
    return merged


def _coerce(value, name):
    """Accept any mapping-like or pair sequence, otherwise raise TypeError."""
    if hasattr(value, "keys"):
        return {key: value[key] for key in value.keys()}
    try:
        return dict(value)
    except (TypeError, ValueError):
        kind = type(value).__name__ if value is not None else "None"
        raise TypeError("%s must be a dict, got %s" % (name, kind))


def merge_all(dicts):
    """Merge a sequence of dictionaries left to right."""
    result = {}
    for item in dicts:
        result = merge_dicts(result, item)
    return result


def deep_merge(dict1, dict2):
    """Like merge_dicts, but nested dicts are merged instead of replaced."""
    merged = dict(dict1)
    for key, new_value in dict2.items():
        old_value = merged.get(key)
        both_dicts = isinstance(old_value, dict) and isinstance(new_value, dict)
        merged[key] = deep_merge(old_value, new_value) if both_dicts else new_value
    return merged


def describe_merge(dict1, dict2):
    """Summarise what a merge of the two dictionaries does."""
    overwritten = sorted(k for k in dict2 if k in dict1)
    added = sorted(k for k in dict2 if k not in dict1)
    kept = sorted(k for k in dict1 if k not in dict2)
    return {
        "overwritten": overwritten,
        "added": added,
        "kept": kept,
        "conflicts": len(overwritten),
    }


def format_dict(mapping):
    """Render a dictionary with keys in a stable order."""
    body = ", ".join("%r: %r" % (k, mapping[k]) for k in sorted(mapping, key=repr))
    return "{%s}" % body


def format_report(dict1, dict2):
    info = describe_merge(dict1, dict2)
    merged = merge_dicts(dict1, dict2)
    lines = ["%s + %s -> %s" % (format_dict(dict1), format_dict(dict2),
                                format_dict(merged))]
    noun = "conflict" if info["conflicts"] == 1 else "conflicts"
    lines.append("  %d %s: %s" % (info["conflicts"], noun,
                                  ", ".join(info["overwritten"]) or "none"))
    lines.append("  added: %s" % (", ".join(info["added"]) or "none"))
    lines.append("  kept: %s" % (", ".join(info["kept"]) or "none"))
    return "\n".join(lines)


def main():
    pairs = [
        ({"a": 1, "b": 2}, {"b": 3, "c": 4}),
        ({"x": 10}, {"y": 20}),
        ({"cfg": {"host": "localhost", "port": 80}}, {"cfg": {"port": 8080}}),
    ]
    for left, right in pairs:
        print(format_report(left, right))
    nested = deep_merge(*pairs[2])
    print("deep:", format_dict(nested["cfg"]))
    print("all:", format_dict(merge_all([pair[0] for pair in pairs])))


if __name__ == "__main__":
    main()

