_MONTH_DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
_WEEKDAYS = ["Monday", "Tuesday", "Wednesday", "Thursday",
             "Friday", "Saturday", "Sunday"]


def is_leap_year(year):
    """True if `year` is a leap year in the proleptic Gregorian calendar."""
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year, month):
    """Length of `month` (1-12) in `year`."""
    if month == 2 and is_leap_year(year):
        return 29
    return _MONTH_DAYS[month - 1]


def parse_date(date_str):
    """Parse 'YYYY-MM-DD' into a (year, month, day) tuple, validating the values."""
    parts = date_str.strip().split("-")
    if len(parts) != 3:
        raise ValueError("date must look like 'YYYY-MM-DD': %r" % date_str)
    if not all(part.isdigit() for part in parts):
        raise ValueError("date fields must be numeric: %r" % date_str)
    year, month, day = (int(part) for part in parts)
    if not 1 <= month <= 12:
        raise ValueError("month out of range in %r" % date_str)
    limit = days_in_month(year, month)
    if not 1 <= day <= limit:
        raise ValueError("day out of range (1-%d) in %r" % (limit, date_str))
    return year, month, day


def _days_from_civil(year, month, day):
    """Serial day number relative to 1970-01-01 (Hinnant's algorithm)."""
    shifted = year - 1 if month <= 2 else year
    era_base = shifted if shifted >= 0 else shifted - 399
    era = era_base // 400
    year_of_era = shifted - era * 400
    month_index = month - 3 if month > 2 else month + 9
    day_of_year = (153 * month_index + 2) // 5 + day - 1
    day_of_era = year_of_era * 365 + year_of_era // 4 - year_of_era // 100 + day_of_year
    return era * 146097 + day_of_era - 719468


def days_between_dates(start_date_str, end_date_str):
    """Signed number of days from `start_date_str` to `end_date_str`."""
    start = _days_from_civil(*parse_date(start_date_str))
    end = _days_from_civil(*parse_date(end_date_str))
    return end - start


def weekday_name(date_str):
    """English weekday name of a 'YYYY-MM-DD' date."""
    serial = _days_from_civil(*parse_date(date_str))
    return _WEEKDAYS[(serial + 3) % 7]


def describe_gap(start_date_str, end_date_str):
    """Human-readable sentence about the gap between two dates."""
    delta = days_between_dates(start_date_str, end_date_str)
    magnitude = abs(delta)
    noun = "day" if magnitude == 1 else "days"
    relation = "after" if delta > 0 else "before"
    end_weekday = weekday_name(end_date_str)
    if delta == 0:
        return "%s is the same day (%s)" % (end_date_str, end_weekday)
    return "%s (%s) is %d %s %s %s" % (end_date_str, end_weekday, magnitude,
                                       noun, relation, start_date_str)


def main():
    pairs = [('2023-01-01', '2023-01-05'),
             ('2023-01-01', '2022-12-25'),
             ('2000-02-28', '2000-03-01'),
             ('1900-02-28', '1900-03-01'),
             ('2024-06-15', '2024-06-15'),
             ('2023-13-01', '2023-01-01')]
    for start, end in pairs:
        try:
            delta = days_between_dates(start, end)
        except ValueError as exc:
            print("%s -> %s : error (%s)" % (start, end, exc))
            continue
        sign = "+" if delta > 0 else ""
        print("%s -> %s : %s%d  | %s" % (start, end, sign, delta,
                                         describe_gap(start, end)))


if __name__ == "__main__":
    main()

