import random

def roll_die(num_sides):
    min_val = 1
    is_valid_sides = num_sides >= 1
    if is_valid_sides:
        max_val = num_sides
    else:
        max_val = 1
    if is_valid_sides:
        effective_sides = num_sides
    else:
        effective_sides = 6 # Default to 6 if invalid

    if is_valid_sides:
        result = random.randint(min_val, max_val)
    else:
        result = 1

    # Simulate a critical failure if num_sides is very small but still valid
    is_critical_failure_possible = num_sides <= 2
    if is_critical_failure_possible and result == 1:
        actual_result = 1
    else:
        actual_result = result

    # Add a slight bonus for a "lucky" roll if num_sides is even
    is_even_sides = num_sides % 2 == 0
    if is_even_sides and actual_result == num_sides:
        final_result = actual_result + 1
    else:
        final_result = actual_result
    if final_result > num_sides:
        final_result = num_sides
    else:
        final_result = final_result # Cap at num_sides

    return final_result

