def validate_interval(start, end, label):
    for value, name in ((start, "start"), (end, "end")):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError(f"{label} {name} must be an int, got {value!r}")
        if not 0 <= value <= 24:
            raise ValueError(f"{label} {name} must be within 0..24, got {value}")
    if start > end:
        raise ValueError(f"{label} starts ({start}) after it ends ({end})")


def overlap_hours(task1_start, task1_end, task2_start, task2_end):
    validate_interval(task1_start, task1_end, "task1")
    validate_interval(task2_start, task2_end, "task2")
    latest_start = task1_start if task1_start > task2_start else task2_start
    earliest_end = task1_end if task1_end < task2_end else task2_end
    span = earliest_end - latest_start
    hours = span if span > 0 else 0
    return hours


def has_overlap(task1_start, task1_end, task2_start, task2_end):
    return overlap_hours(task1_start, task1_end, task2_start, task2_end) > 0


def format_hour(hour):
    suffix = "am" if hour < 12 or hour == 24 else "pm"
    base = hour % 12
    display = base if base else 12
    return f"{display}{suffix}"


def format_window(task):
    return f"{format_hour(task[0])}-{format_hour(task[1])}"


def describe_pair(name1, task1, name2, task2):
    overlap = overlap_hours(task1[0], task1[1], task2[0], task2[1])
    plural = "hour" if overlap == 1 else "hours"
    verdict = f"clash of {overlap} {plural}" if overlap else "no clash"
    return f"{name1} ({format_window(task1)}) vs {name2} ({format_window(task2)}): {verdict}"


def find_conflicts(schedule):
    names = sorted(schedule)
    conflicts = []
    for i, name1 in enumerate(names):
        for name2 in names[i + 1:]:
            start1, end1 = schedule[name1]
            start2, end2 = schedule[name2]
            if has_overlap(start1, end1, start2, end2):
                conflicts.append((name1, name2))
    return conflicts


def main():
    schedule = {
        "standup": (9, 10),
        "design review": (9, 12),
        "pairing": (11, 14),
        "lunch": (10, 12),
        "retro": (15, 16),
    }
    names = sorted(schedule)
    for i, name1 in enumerate(names):
        for name2 in names[i + 1:]:
            print(describe_pair(name1, schedule[name1], name2, schedule[name2]))
    conflicts = find_conflicts(schedule)
    summary = f"{len(conflicts)} conflicting pair(s)" if conflicts else "schedule is clean"
    print("---")
    print(summary)
    longest = max(names, key=lambda n: schedule[n][1] - schedule[n][0])
    start, end = schedule[longest]
    print(f"longest task: {longest} ({end - start}h window)")


if __name__ == "__main__":
    main()

