def find_second_smallest(numbers):
    """Return the second smallest distinct value in numbers."""
    validate(numbers)
    smallest = None
    second = None
    for value in numbers:
        if smallest is None or value < smallest:
            second = smallest
            smallest = value
        elif value != smallest and (second is None or value < second):
            second = value
    if second is None:
        raise ValueError("numbers must contain at least two distinct values")
    return second


def validate(numbers):
    """Raise a descriptive error if numbers is not a usable list of numbers."""
    if not isinstance(numbers, (list, tuple)):
        kind = type(numbers).__name__
        raise TypeError("expected a list of numbers, got " + kind)
    size = len(numbers)
    if size < 2:
        detail = "one element" if size == 1 else "no elements"
        raise ValueError("expected at least two numbers, got " + detail)
    for index, value in enumerate(numbers):
        ok = isinstance(value, (int, float)) and not isinstance(value, bool)
        if not ok:
            raise TypeError("element %d is not a number: %r" % (index, value))


def parse_numbers(text):
