    cleaned = text.replace(",", " ") if "," in text else text
    values = []
    for token in cleaned.split():
        number = float(token) if ("." in token or "e" in token.lower()) else int(token)
        values.append(number)
    return values


def format_number(value):
    """Render a number compactly, dropping trailing zeros from floats."""
    if isinstance(value, int):
        return str(value)
    text = "%.6f" % value
