def describe(numbers):
    """Return a one-line report about the second smallest value."""
    try:
        result = find_second_smallest(numbers)
    except (TypeError, ValueError) as error:
        return "error: %s" % error
    head = numbers if len(numbers) <= 6 else numbers[:6]
    items = ", ".join(format_number(v) for v in head)
    listing = items if len(numbers) <= 6 else items + ", ..."
    return "[%s] -> %s" % (listing, format_number(result))


def main():
    inputs = [
        "5 1 8 2 9",
        "10, 20, 30, 5",
        "3.5 2.25 2.25 -1",
