def validate_matrix(matrix):
    if not isinstance(matrix, list):
        raise TypeError("matrix must be a list of lists")
    width = len(matrix[0]) if matrix else 0
    for row in matrix:
        if not isinstance(row, list):
            raise TypeError("every row must be a list")
        if len(row) != width:
            raise ValueError("all rows must have the same length")
        for value in row:
            kind = "bool" if isinstance(value, bool) else type(value).__name__
            if kind not in ("int", "float"):
                raise TypeError("matrix entries must be int or float, got " + kind)
    return width


def transpose_matrix(matrix):
    width = validate_matrix(matrix)
    return [[row[col] for row in matrix] for col in range(width)]


def shape(matrix):
    rows = len(matrix)
    cols = len(matrix[0]) if rows else 0
    return rows, cols


def is_symmetric(matrix):
    return matrix == transpose_matrix(matrix)


def format_cell(value):
    return ("%g" % value) if isinstance(value, float) else str(value)


def format_matrix(matrix):
    if not matrix:
        return "(empty)"
    cells = [[format_cell(v) for v in row] for row in matrix]
    width = max(len(c) for row in cells for c in row) if cells[0] else 0
    lines = []
    for row in cells:
        lines.append("[ " + "  ".join(c.rjust(width) for c in row) + " ]")
    return "\n".join(lines)


def orientation_of(rows, cols):
    if rows == cols:
        return "square"
    return "wide" if cols > rows else "tall"


