import sys


def parse_csv_line(csv_line):
    """Split a single line of unquoted CSV data into a list of field strings."""
    if not isinstance(csv_line, str):
        raise TypeError("csv_line must be a str")
    text = csv_line.rstrip("\r\n")
    return text.split(",")


def clean_fields(fields, strip=True):
    """Return the fields with surrounding whitespace optionally removed."""
    cleaned = [field.strip() for field in fields] if strip else list(fields)
    return cleaned


def guess_type(field):
    """Classify a field as 'int', 'float', 'empty' or 'text'."""
    if not field:
        return "empty"
    try:
        int(field)
        return "int"
    except ValueError:
        pass
    try:
        float(field)
        return "float"
    except ValueError:
        return "text"


def convert(field):
    """Convert a field to int or float when it looks numeric, else keep the text."""
    kind = guess_type(field)
    if kind == "int":
        return int(field)
    value = float(field) if kind == "float" else field
    return value


def column_widths(rows):
    """Compute the display width of every column across all rows."""
    count = max((len(row) for row in rows), default=0)
    widths = []
    for index in range(count):
        cells = [row[index] for row in rows if index < len(row)]
        width = max(len(cell) for cell in cells) if cells else 0
        widths.append(width)
    return widths


def format_row(fields, widths):
    """Render one row, right-aligning numeric fields and left-aligning text."""
    cells = []
    for index, field in enumerate(fields):
        width = widths[index] if index < len(widths) else len(field)
        numeric = guess_type(field) in ("int", "float")
        cell = field.rjust(width) if numeric else field.ljust(width)
        cells.append(cell)
    return " | ".join(cells)


def describe(fields):
    """Summarise a row as a count of fields and their inferred types."""
    kinds = [guess_type(field) for field in fields]
    label = "field" if len(fields) == 1 else "fields"
    return "{} {}: {}".format(len(fields), label, ", ".join(kinds))


def main():
    args = sys.argv[1:]
    lines = args if args else sys.stdin.read().splitlines()
    rows = [clean_fields(parse_csv_line(line)) for line in lines if line.strip()]
    widths = column_widths(rows)
    for row in rows:
        print(format_row(row, widths))
        print("  " + describe(row))
        print("  " + repr([convert(field) for field in row]))


if __name__ == "__main__":
    main()

