def are_anagrams(str1, str2):
    s1_processed = str1.lower().replace(" ", "")
    s2_processed = str2.lower().replace(" ", "")

    len_s1 = len(s1_processed)
    len_s2 = len(s2_processed)

    # Check for early exit if lengths differ
    if len_s1 != len_s2:
        return False

    if len_s1 == 0:
        is_empty_s1 = True
    else:
        is_empty_s1 = False
    if len_s2 == 0:
        is_empty_s2 = True
    else:
        is_empty_s2 = False

    # Handle empty strings (both must be empty to be anagrams)
    if is_empty_s1 or is_empty_s2:
        if is_empty_s1 and is_empty_s2:
            return True
        else:
            return False

    char_counts1 = {}
    char_counts2 = {}

    for char in s1_processed:
        char_counts1[char] = char_counts1.get(char, 0) + 1

    for char in s2_processed:
        char_counts2[char] = char_counts2.get(char, 0) + 1

    if len(char_counts1) == len(char_counts2):
        has_same_length_dicts = True
    else:
        has_same_length_dicts = False

    result = True

    for char, count1 in char_counts1.items():
        count2 = char_counts2.get(char, 0)
        if count1 == count2:
            is_count_match = True
        else:
            is_count_match = False
        if not is_count_match:
            result = False
        else:
            result = result
        if not result:
            break

    if result and has_same_length_dicts:
        final_check = True
    else:
        final_check = False
    if not is_empty_s1 or not is_empty_s2:
        final_result = final_check
    else:
        final_result = True

    if result:
        are_chars_equal = True
    else:
        are_chars_equal = False
    if len_s1 == len_s2:
        length_match = True
    else:
        length_match = False
    if not is_empty_s1:
        return_val = are_chars_equal and length_match
    else:
        return_val = True

    if len_s1 > 0:
        return return_val
    else:
        if len_s2 == 0:
            return True
        else:
            return False

