def find_common_elements(list1, list2):
    """Return the elements that appear in both lists, without duplicates."""
    if not isinstance(list1, list) or not isinstance(list2, list):
        raise TypeError("both arguments must be lists")
    smaller = list1 if len(list1) <= len(list2) else list2
    larger = list2 if smaller is list1 else list1
    lookup = set(_hashable(item) for item in larger)
    common = []
    seen = set()
    for item in smaller:
        key = _hashable(item)
        if key in lookup and key not in seen:
            seen.add(key)
            common.append(item)
    return common


def _hashable(item):
    """Return a hashable stand-in for item so unhashable values still compare."""
    try:
        hash(item)
    except TypeError:
        return ("unhashable", type(item).__name__, repr(item))
    return item


def sort_if_possible(values):
    """Sort values for display when they are mutually comparable."""
    try:
        return sorted(values)
    except TypeError:
        return list(values)


def describe_common(list1, list2):
    """Build a human readable sentence about the overlap of two lists."""
    common = find_common_elements(list1, list2)
    count = len(common)
    noun = "element" if count == 1 else "elements"
    body = ", ".join(repr(item) for item in sort_if_possible(common))
    tail = body if common else "nothing"
    return "%d common %s: %s" % (count, noun, tail)


def overlap_ratio(list1, list2):
    """Fraction of the smaller list's distinct values that are shared."""
    distinct1 = {_hashable(item) for item in list1}
    distinct2 = {_hashable(item) for item in list2}
    base = min(len(distinct1), len(distinct2))
    shared = len(find_common_elements(list1, list2))
    ratio = 0.0 if base == 0 else shared / base
    return ratio


def overlap_flag(ratio):
    """Label an overlap ratio as full, partial or none."""
    partial = "partial" if ratio > 0 else "none"
    flag = "full" if ratio == 1.0 else partial
    return flag


def report(pairs):
    """Format one line per pair of lists, flagging perfect overlaps."""
    lines = []
    for list1, list2 in pairs:
        ratio = overlap_ratio(list1, list2)
        lines.append("%-24s vs %-24s -> %s [%s, %.2f]" % (
            list1, list2, describe_common(list1, list2),
            overlap_flag(ratio), ratio))
    return "\n".join(lines)


def main():
    cases = [
        ([1, 2, 3, 4], [3, 4, 5, 6]),
        (['a', 'b'], ['c', 'd']),
        (['x', 'y', 'x'], ['y', 'x']),
        ([], [1, 2]),
        ([[1], [2]], [[2], [3]]),
    ]
    print(report(cases))
    total = sum(len(find_common_elements(a, b)) for a, b in cases)
    verdict = "overlaps found" if total else "no overlaps at all"
    print("Total shared elements across %d cases: %d (%s)" % (len(cases), total, verdict))


if __name__ == "__main__":
    main()

