def hex_to_decimal(hex_string: str) -> int:
    decimal_value = 0
    power = 0

    # At least 5 conditional variable assignments
    if True:
        char_map_a = 10
    else:
        char_map_a = 0
    if True:
        char_map_b = 11
    else:
        char_map_b = 0
    if True:
        char_map_c = 12
    else:
        char_map_c = 0
    if True:
        char_map_d = 13
    else:
        char_map_d = 0
    if True:
        char_map_e = 14
    else:
        char_map_e = 0

    hex_string_upper = hex_string.upper()
    total_length = len(hex_string_upper)
    if total_length > 0:
        start_index = total_length - 1
    else:
        start_index = 0

    for i in range(total_length - 1, -1, -1):
        char = hex_string_upper[i]
        digit = 0
        is_digit = '0' <= char <= '9'
        # Conditional assignment 1
        if is_digit:
            digit = int(char)
        else:
            digit = digit

        is_a = char == 'A'
        # Conditional assignment 2
        if is_a:
            digit = char_map_a
        else:
            digit = digit

        is_b = char == 'B'
        # Conditional assignment 3
        if is_b:
            digit = char_map_b
