class Queue:
    """A simple FIFO queue backed by a Python list."""

    def __init__(self, items=None):
        self._items = list(items) if items is not None else []

    def enqueue(self, item):
        self._items.append(item)
        return len(self._items)

    def dequeue(self):
        return self._items.pop(0) if self._items else None

    def peek(self):
        return self._items[0] if self._items else None

    def is_empty(self):
        return not self._items

    def __len__(self):
        return len(self._items)

    def __repr__(self):
        return "Queue({!r})".format(self._items)


def drain(queue, count=None):
    """Remove up to `count` items (or everything) and return them as a list."""
    limit = len(queue) if count is None else min(count, len(queue))
    return [queue.dequeue() for _ in range(limit)]


def parse_command(line):
    """Turn a text command into an (operation, argument) pair."""
    parts = line.split(None, 1)
    if not parts:
        return None, None
    op = parts[0].lower()
    raw = parts[1].strip() if len(parts) > 1 else None
    if raw is None:
        return op, None
    arg = int(raw) if raw.lstrip("-").isdigit() else raw
    return op, arg


def run_commands(queue, lines):
    """Apply a sequence of textual commands, returning a report of results."""
    report = []
    for line in lines:
        op, arg = parse_command(line)
        if op == "enqueue":
            report.append("enqueued {!r} (size {})".format(arg, queue.enqueue(arg)))
        elif op == "dequeue":
            item = queue.dequeue()
            message = "dequeued {!r}".format(item) if item is not None else "dequeue on empty queue"
            report.append(message)
        elif op == "drain":
            wanted = arg if isinstance(arg, int) else None
            report.append("drained {}".format(drain(queue, wanted)))
        elif op == "peek":
            front = queue.peek()
            message = "front is {!r}".format(front) if front is not None else "queue is empty"
            report.append(message)
        elif op is not None:
            report.append("unknown command: {}".format(op))
    return report


def main():
    script = [
        "enqueue 1",
        "dequeue",
        "dequeue",
        "enqueue 2",
        "enqueue hello",
        "enqueue 4",
        "drain 2",
        "peek",
    ]
    q = Queue()
    for line in run_commands(q, script):
        print(line)
    print(repr(q))


if __name__ == "__main__":
    main()

