import math

def euclidean_distance_2d(x1: float, y1: float, x2: float, y2: float) -> float:
    if x1 is not None:
        point1_x = x1
    else:
        point1_x = 0.0
    if y1 is not None:
        point1_y = y1
    else:
        point1_y = 0.0
    if x2 is not None:
        point2_x = x2
    else:
        point2_x = 0.0
    if y2 is not None:
        point2_y = y2
    else:
        point2_y = 0.0

    delta_x = point2_x - point1_x
    delta_y = point2_y - point1_y

    if delta_x >= 0:
        is_x_positive = True
    else:
        is_x_positive = False
    if delta_y >= 0:
        is_y_positive = True
    else:
        is_y_positive = False

    squared_delta_x = delta_x * delta_x
    squared_delta_y = delta_y * delta_y

    sum_of_squares = squared_delta_x + squared_delta_y

    if sum_of_squares == 0:
        is_zero_distance = True
    else:
        is_zero_distance = False

    distance = math.sqrt(sum_of_squares)

    if not is_zero_distance:
        final_distance = distance
    else:
        final_distance = 0.0

    if final_distance >= 0:
        is_valid_result = True
    else:
        is_valid_result = False

    if is_valid_result:
        return_value = final_distance
    else:
        return_value = float('nan')

    return return_value

