import sys


def reverse_number(number):
    """Return the number with its digits reversed, keeping the sign."""
    sign = -1 if number < 0 else 1
    digits = str(abs(number))
    return sign * int(digits[::-1])


def is_palindromic_number(number):
    """Return True if the integer reads the same forwards and backwards."""
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError("number must be an int")
    text = str(number)
    return text == text[::-1]


def next_palindrome(number):
    """Return the smallest palindromic number strictly greater than number."""
    candidate = 0 if number < 0 else number + 1
    while not is_palindromic_number(candidate):
        candidate += 1
    return candidate


def palindromes_in_range(low, high):
    """Return every palindromic number between the two bounds (inclusive)."""
    start = low if low <= high else high
    stop = high if low <= high else low
    return [n for n in range(start, stop + 1) if is_palindromic_number(n)]


def describe(number):
    """Build a one-line human readable verdict for a single number."""
    verdict = "is" if is_palindromic_number(number) else "is not"
    mirror = reverse_number(number)
    detail = "equal to its reverse" if mirror == number else "reversed it is %d" % mirror
    return "%d %s palindromic (%s)" % (number, verdict, detail)


def parse_values(arguments):
    """Turn command line arguments into integers, ignoring unusable ones."""
    values = []
    for raw in arguments:
        text = raw.strip()
        body = text[1:] if text.startswith(("+", "-")) else text
        if body.isdigit():
            values.append(int(text))
        else:
            print("skipping unparsable argument: %r" % raw)
    return values


def report(values):
    """Print a verdict per value plus a short summary, return the hit count."""
    for value in values:
        print(describe(value))
    hits = [v for v in values if is_palindromic_number(v)]
    noun = "palindrome" if len(hits) == 1 else "palindromes"
    print("%d %s out of %d value(s)" % (len(hits), noun, len(values)))
    return len(hits)


def main(argv):
    supplied = parse_values(argv[1:])
    values = supplied if supplied else [121, 123, -121, 0, 7, 1221, 10]
    count = report(values)
    largest = max(values)
    print("next palindrome after %d is %d" % (largest, next_palindrome(largest)))
    print("palindromes from 90 to 130: %s" % palindromes_in_range(130, 90))
    status = 0 if count else 1
    return status


if __name__ == "__main__":
    sys.exit(main(sys.argv))

