def validate_range_sequence(numbers):
    """Check that numbers is a list of n-1 distinct ints from 1..n."""
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list, got " + type(numbers).__name__)
    n = len(numbers) + 1
    seen = set()
    for value in numbers:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("all entries must be ints, got " + repr(value))
        if not 1 <= value <= n:
            side = "below 1" if value < 1 else "above %d" % n
            raise ValueError("entry %d is out of range (%s)" % (value, side))
        if value in seen:
            raise ValueError("entry %d appears more than once" % value)
        seen.add(value)
    return n


def find_missing_number(numbers):
    """Return the single value from 1..n that is absent from numbers."""
    n = validate_range_sequence(numbers)
    complete_total = n * (n + 1) // 2
    return complete_total - sum(numbers)


def describe_sequence(numbers, limit=6):
    """Render a sequence compactly, truncating long ones."""
    short = len(numbers) <= limit
    head = numbers if short else numbers[:limit]
    tail = "" if short else ", ..."
    return "[" + ", ".join(str(v) for v in head) + tail + "]"


def parse_sequence(text):
    """Read a sequence written as '1, 2, 4' or '1 2 4' (brackets optional)."""
    stripped = text.strip().strip("[]")
    parts = stripped.split(",") if "," in stripped else stripped.split()
    cleaned = [part.strip() for part in parts if part.strip()]
    for part in cleaned:
        if not part.lstrip("+-").isdigit():
            raise ValueError("cannot parse %r as an integer" % part)
    return [int(part) for part in cleaned]


def format_report(numbers, missing):
    """One human-readable line about a solved case."""
    n = len(numbers) + 1
    place = "boundary" if missing in (1, n) else "interior"
    gap_word = "value" if n == 2 else "values"
    return "%s over 1..%d (%d %s given): missing %d (%s)" % (
        describe_sequence(numbers), n, len(numbers), gap_word, missing, place)


def report_case(raw):
    """Handle one case given either as a list or as text."""
    try:
        numbers = parse_sequence(raw) if isinstance(raw, str) else list(raw)
        missing = find_missing_number(numbers)
    except (TypeError, ValueError) as exc:
        return "%r -> error: %s" % (raw, exc)
    return format_report(numbers, missing)


