        "[2 3 4 5 6 7]",
        [1, 2, 2],
        [1, 2, 9],
    ]
    for raw in cases:
        print(report_case(raw))
    total = len(cases)
    noun = "case" if total == 1 else "cases"
    print("processed %d %s" % (total, noun))


if __name__ == "__main__":
