def parse_measurement(text, unit):
    """Convert a textual measurement to kilograms or metres."""
    cleaned = text.strip().lower().replace(",", ".")
    if cleaned.endswith(unit):
        cleaned = cleaned[:-len(unit)].strip()
    try:
        value = float(cleaned)
    except ValueError:
        raise ValueError("cannot read measurement: %r" % text)
    scale = 100.0 if unit == "m" and value > 3 else 1.0
    return value / scale


def calculate_bmi(weight_kg, height_m):
    """Return the BMI rounded to two decimals."""
    if weight_kg <= 0 or height_m <= 0:
        raise ValueError("weight and height must be positive")
    return round(weight_kg / (height_m * height_m), 2)


def healthy_weight_range(height_m):
    """Return the weight interval matching a normal BMI for this height."""
    lower = 18.5 * height_m * height_m
    upper = 24.9 * height_m * height_m
    return round(lower, 1), round(upper, 1)


def advise(weight_kg, height_m):
    """Suggest how much weight to gain or lose to reach a normal BMI."""
    lower, upper = healthy_weight_range(height_m)
    if lower <= weight_kg <= upper:
        return "weight is already in the healthy range"
    verb = "gain" if weight_kg < lower else "lose"
    delta = lower - weight_kg if weight_kg < lower else weight_kg - upper
    amount = "%.1f kg" % delta if delta >= 0.1 else "less than 0.1 kg"
    return "%s %s to reach a normal BMI" % (verb, amount)


def classify_bmi(bmi):
    """Return the standard WHO category for a BMI value."""
    if bmi < 18.5:
        category = "underweight" if bmi >= 16.0 else "severely underweight"
    elif bmi < 25.0:
        category = "normal weight"
    elif bmi < 30.0:
        category = "overweight"
    else:
        category = "obese" if bmi < 40.0 else "severely obese"
    return category


def report(weight_text, height_text):
    """Build a one-line report from raw textual input."""
    weight_kg = parse_measurement(weight_text, "kg")
    height_m = parse_measurement(height_text, "m")
    bmi = calculate_bmi(weight_kg, height_m)
    label = classify_bmi(bmi)
    return "BMI %.2f (%s): %s" % (bmi, label, advise(weight_kg, height_m))


