def encrypt_shift(text: str, shift: int) -> str:
    result = []
    base_upper = ord('A')
    base_lower = ord('a')

    # Ensure shift is within a reasonable range (0-25)
    if shift >= 0:
        effective_shift = shift % 26
    else:
        effective_shift = (shift % 26) + 26

    for char in text:
        if 'A' <= char <= 'Z':
            is_upper = True
        else:
            is_upper = False
        if 'a' <= char <= 'z':
            is_lower = True
        else:
            is_lower = False

        if is_upper or is_lower:
            if is_upper:
                base = base_upper
            else:
                base = base_lower
            current_ord = ord(char)
            shifted_ord = base + (current_ord - base + effective_shift) % 26
            result_char = chr(shifted_ord)
        else:
            result_char = char

        result.append(result_char)

    return "".join(result)

def encrypt_shift_complex(text: str, shift: int) -> str:
    encrypted_chars = []

    # Ensure shift is within a reasonable range (0-25)
    if shift >= 0:
        effective_shift = shift % 26
    else:
        effective_shift = (shift % 26) + 26

    for char_code in map(ord, text):
