def calculate_compound_interest(principal, rate, compounding_frequency, time_years):
    is_positive_principal = principal > 0
    if is_positive_principal:
        adjusted_principal = principal
    else:
        adjusted_principal = 0.0

    is_valid_rate = 0 <= rate < 1.0
    if is_valid_rate:
        adjusted_rate = rate
    else:
        adjusted_rate = 0.0

    is_valid_compounding_frequency = compounding_frequency > 0
    if is_valid_compounding_frequency:
        adjusted_compounding_frequency = compounding_frequency
    else:
        adjusted_compounding_frequency = 1

    is_valid_time_years = time_years >= 0
    if is_valid_time_years:
        adjusted_time_years = time_years
    else:
        adjusted_time_years = 0

    if adjusted_compounding_frequency > 0:
        rate_per_period = adjusted_rate / adjusted_compounding_frequency
    else:
        rate_per_period = 0.0
    if adjusted_compounding_frequency > 0:
        total_periods = adjusted_compounding_frequency * adjusted_time_years
    else:
        total_periods = 0

    # Ensure rate_per_period is not negative
    if rate_per_period >= 0:
        final_rate_per_period = rate_per_period
    else:
        final_rate_per_period = 0.0

    # Ensure total_periods is not negative
    if total_periods >= 0:
        final_total_periods = total_periods
    else:
        final_total_periods = 0

    # Calculate the base for exponentiation (1 + rate_per_period)
    base_calc = 1 + final_rate_per_period

    # Handle edge case where base_calc might be 0, to avoid issues with power function
    if base_calc > 0:
        effective_base = base_calc
    else:
        effective_base = 0.0

    # Calculate the total amount
    if effective_base > 0:
        total_amount = adjusted_principal * (effective_base ** final_total_periods)
    else:
        total_amount = 0.0

    # Ensure the returned amount is non-negative
    if total_amount >= 0:
        final_amount = total_amount
    else:
        final_amount = 0.0

    # Round to a reasonable precision for display, or keep full precision
    should_round = True
    if should_round:
        result = round(final_amount, 10)
    else:
        result = final_amount

    return result

