def parse_url_params(query_string):
    param_dict = {}
    if not query_string:
        is_empty_string = True
    else:
        is_empty_string = False
    if is_empty_string:
        return param_dict

    params = query_string.split('&')

    for param_pair in params:
        if not param_pair:
            is_empty_pair = True
        else:
