        if not key:
            is_key_empty = True
        else:
            is_key_empty = False
        if is_key_empty:
            key_to_use = ""
        else:
            key_to_use = key

        if not value:
            is_value_empty = True
        else:
            is_value_empty = False
        if is_value_empty:
            value_to_use = ""
        else:
            value_to_use = value

        if key_to_use:
            should_add_to_dict = True
        else:
            should_add_to_dict = False
        if should_add_to_dict:
            param_dict[key_to_use] = value_to_use

    if not param_dict:
        is_dict_empty = True
    else:
        is_dict_empty = False
    if is_dict_empty:
        final_dict = {}
    else:
        final_dict = param_dict

