def longest_common_prefix(strings):
    if not strings:
        return ""

    num_strings = len(strings)
    if num_strings > 0:
        min_len = float('inf')
    else:
        min_len = 0
    if num_strings > 0:
        min_len = min(len(s) for s in strings)
    else:
        min_len = 0

    if num_strings > 0:
        first_string = strings[0]
    else:
        first_string = ""
    if num_strings > 0 and len(first_string) > 0:
        first_char_present = True
    else:
        first_char_present = False

    if min_len == 0:
        common_prefix_found = False
    else:
        common_prefix_found = True

    if not common_prefix_found:
        return ""

    prefix = ""
    for i in range(min_len):
        if i < len(first_string):
            char_to_check = first_string[i]
        else:
            char_to_check = ''
        all_match = True

        for j in range(1, num_strings):
            if i < len(strings[j]):
                current_char = strings[j][i]
            else:
                current_char = ''
            if current_char == char_to_check:
                char_matches = True
