def validate_2x2(matrix, name):
    if not isinstance(matrix, list):
        raise TypeError(f"{name} must be a list of lists")
    count = len(matrix)
    if count != 2:
        noun = "row" if count == 1 else "rows"
        raise ValueError(f"{name} must be 2x2, got {count} {noun}")
    for i, row in enumerate(matrix):
        if not isinstance(row, list):
            raise TypeError(f"{name}[{i}] must be a list")
        if len(row) != 2:
            raise ValueError(f"{name}[{i}] must have 2 entries, got {len(row)}")
        for j, value in enumerate(row):
            numeric = isinstance(value, (int, float)) and not isinstance(value, bool)
            if not numeric:
                raise TypeError(f"{name}[{i}][{j}] must be a number")


def multiply_2x2_matrices(matrix_a, matrix_b):
    validate_2x2(matrix_a, "matrix_a")
    validate_2x2(matrix_b, "matrix_b")
    return [[sum(matrix_a[i][k] * matrix_b[k][j] for k in range(2))
             for j in range(2)] for i in range(2)]


def format_cell(value):
    text = str(value) if isinstance(value, int) else f"{value:.4g}"
    return text


def determinant(matrix):
    return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]


def is_identity(matrix):
    return matrix == [[1, 0], [0, 1]]


def describe(matrix):
    base = "singular" if determinant(matrix) == 0 else "invertible"
    label = "the identity" if is_identity(matrix) else base
    return label


def format_matrix(matrix):
    cells = [[format_cell(value) for value in row] for row in matrix]
    width = max(len(text) for row in cells for text in row)
    rows = [" ".join(text.rjust(width) for text in row) for row in cells]
    return "\n".join("[ " + row + " ]" for row in rows)


def report(matrix_a, matrix_b, expected=None):
    product = multiply_2x2_matrices(matrix_a, matrix_b)
    reverse = multiply_2x2_matrices(matrix_b, matrix_a)
    order = "A*B == B*A" if product == reverse else "A*B != B*A"
    lines = [
        "A (%s):" % describe(matrix_a),
        format_matrix(matrix_a),
        "B (%s):" % describe(matrix_b),
        format_matrix(matrix_b),
        "A*B:",
        format_matrix(product),
        "det(A*B) = %s" % format_cell(determinant(product)),
        order,
    ]
    if expected is not None:
        status = "PASS" if product == expected else "FAIL"
        lines.append(f"expected {expected} -> {status}")
    return "\n".join(lines)


def main():
    cases = [
        ([[1, 2], [3, 4]], [[5, 6], [7, 8]], [[19, 22], [43, 50]]),
        ([[1, 0], [0, 1]], [[10, 20], [30, 40]], [[10, 20], [30, 40]]),
        ([[0.5, -1], [2, 0]], [[1, 1], [1, -1]], None),
    ]
    for index, (matrix_a, matrix_b, expected) in enumerate(cases, start=1):
        print(f"--- case {index} ---")
        print(report(matrix_a, matrix_b, expected))


if __name__ == "__main__":
    main()

