def _as_number(value, index):
    """Return value as a float, rejecting non-numeric data points."""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        kind = "boolean" if isinstance(value, bool) else type(value).__name__
        raise TypeError("data[%d] must be numeric, got %s" % (index, kind))
    return float(value)


def calculate_sma(data, window_size):
    """Simple moving average of data over window_size consecutive points."""
    if isinstance(window_size, bool) or not isinstance(window_size, int):
        raise TypeError("window_size must be an integer")
    if window_size < 1:
        raise ValueError("window_size must be at least 1")
    points = [_as_number(v, i) for i, v in enumerate(data)]
    if window_size > len(points):
        return []
    total = sum(points[:window_size])
    averages = [total / window_size]
    for i in range(window_size, len(points)):
        total += points[i] - points[i - window_size]
