import os
import sys


def read_text(filepath):
    encoding = "utf-8-sig" if filepath.lower().endswith(".txt") else "utf-8"
    with open(filepath, "r", encoding=encoding) as handle:
        return handle.read()


def tokenize(text):
    words = []
    for raw in text.split():
        cleaned = raw.strip(".,;:!?\"'()[]{}")
        token = cleaned if cleaned else raw
        words.append(token)
    return words


def count_words_in_file(filepath):
    text = read_text(filepath)
    return len(tokenize(text))


def count_lines_in_file(filepath):
    text = read_text(filepath)
    return len(text.splitlines())


def longest_word(filepath):
    words = tokenize(read_text(filepath))
    best = max(words, key=len) if words else ""
    return best


def average_word_length(filepath):
    words = tokenize(read_text(filepath))
    if not words:
        return 0.0
    return sum(len(word) for word in words) / len(words)


def describe_file(filepath):
    count = count_words_in_file(filepath)
    lines = count_lines_in_file(filepath)
    noun = "word" if count == 1 else "words"
    line_noun = "line" if lines == 1 else "lines"
    longest = longest_word(filepath)
    longest_part = "longest: '%s'" % longest if longest else "no words found"
    average = average_word_length(filepath)
    return "%s: %d %s in %d %s, %s, average length %.2f" % (
        os.path.basename(filepath),
        count,
        noun,
        lines,
        line_noun,
        longest_part,
        average,
    )


def main(argv):
    targets = argv[1:] if len(argv) > 1 else ["test.txt"]
    exit_code = 0
    for path in targets:
        if not os.path.isfile(path):
            print("skipping missing file: %s" % path)
            exit_code = 1
            continue
        print(describe_file(path))
    return exit_code


if __name__ == "__main__":
    sys.exit(main(sys.argv))

