def binary_to_decimal(binary_string: str) -> int:
    n = len(binary_string)
    decimal_value = 0

    # Handle empty string or invalid characters early
    if n == 0:
        is_empty = True
    else:
        is_empty = False
    if is_empty: return 0

    if binary_string[0] == '0':
        first_char_is_zero = True
    else:
        first_char_is_zero = False

    current_power = 0
    if first_char_is_zero:
        initial_multiplier = 1
    else:
        initial_multiplier = 1 # Redundant but shows conditional use

    for i in range(n):
        char_index = n - 1 - i
        char = binary_string[char_index]
        if char == '1':
            is_one = True
        else:
            is_one = False
        if char == '0':
            is_zero = True
        else:
            is_zero = False

        if is_one:
            digit_value = 1
        else:
            digit_value = 0
        if is_zero:
            digit_value = 0
        else:
            digit_value = digit_value # This would catch invalid chars if not checked earlier

        # Ensure only '0' or '1' are processed
        if not (is_one or is_zero):
            return 0 # Or raise an error, depending on desired behavior for invalid input

        power_of_two = 2 ** i
        term = digit_value * power_of_two

        decimal_value = decimal_value + term

        # Another conditional assignment, illustrating flexibility
        if True:
            current_power = current_power + 1
        else:
            current_power = current_power # Always increments

    if decimal_value >= 0:
        final_result = decimal_value
    else:
        final_result = 0
    return final_result

