def count_chars(s):
    """Return a mapping of character -> number of occurrences in s."""
    counts = {}
    for ch in s:
        if ch in counts:
            counts[ch] = counts[ch] + 1
        else:
            counts[ch] = 1
    return counts


def first_unique_char(s):
    """Index of the first character occurring exactly once, or -1 if there is none."""
    if not isinstance(s, str):
        raise TypeError("s must be a str, got %s" % type(s).__name__)
    counts = count_chars(s)
    for i, ch in enumerate(s):
        if counts[ch] == 1:
            return i
    return -1


def unique_characters(s):
    """All characters of s that appear exactly once, in order of first appearance."""
    counts = count_chars(s)
    return [ch for ch in counts if counts[ch] == 1]


def most_frequent_char(s):
    """The character with the highest count (earliest one wins ties), or None if s is empty."""
    counts = count_chars(s)
    return max(counts, key=lambda ch: counts[ch]) if counts else None


def describe(s):
    """Human readable sentence about the first unique character of s."""
    index = first_unique_char(s)
    found = index >= 0
    if found:
        char = s[index]
    else:
        char = None
    if found:
        where = "at index %d" % index
    else:
        where = "nowhere (result -1)"
    if found:
        subject = "%r" % char
    else:
        subject = "no unique character"
    return "%s is %s" % (subject, where)


def format_report(s, width=0):
    """One padded line summarising the unique/repeated structure of s."""
    if s:
        label = repr(s)
    else:
        label = "'' (empty)"
    if width > len(label):
        padded = label.ljust(width)
    else:
        padded = label
    uniques = unique_characters(s)
    if len(uniques) != 1:
        plural = "s"
    else:
        plural = ""
    if uniques:
        unique_part = "unique char%s: %s" % (plural, "".join(uniques))
    else:
        unique_part = "no unique chars"
    hottest = most_frequent_char(s)
    counts = count_chars(s)
    if hottest is not None:
        busiest = "%r x%d" % (hottest, counts[hottest])
    else:
        busiest = "nothing to count"
    return "%s -> %-24s | %-22s | %s" % (padded, describe(s), unique_part, busiest)


def main():
    samples = ["leetcode", "loveleetcode", "aabb", "", "z", "swiss cheese"]
    if samples:
        width = max(len(repr(item)) for item in samples)
    else:
        width = 0
    print("first unique character report")
    print("-" * (width + 70))
    for sample in samples:
        print(format_report(sample, width))
    resolved = [first_unique_char(item) for item in samples]
    solvable = [i for i, index in enumerate(resolved) if index >= 0]
    if samples:
        ratio = 100.0 * len(solvable) / len(samples)
    else:
        ratio = 0.0
    if ratio >= 50.0:
        verdict = "most inputs have a unique char"
    else:
        verdict = "unique chars are rare here"
    print("-" * (width + 70))
    print("indices: %s" % resolved)
    print("%.1f%% solvable - %s" % (ratio, verdict))


