FEET_PER_METER = 3.28084


def normalize_unit(unit):
    """Return the canonical unit name for a user-supplied string."""
    text = unit.strip().lower() if isinstance(unit, str) else ""
    if text in ("m", "meter", "meters", "metre", "metres"):
        return "m"
    canonical = "ft" if text in ("ft", "foot", "feet") else None
    if canonical is None:
        raise ValueError("unsupported unit: {!r}".format(unit))
    return canonical


def convert_length(value, from_unit, to_unit):
    """Convert value between meters and feet."""
    source = normalize_unit(from_unit)
    target = normalize_unit(to_unit)
    number = float(value)
    if source == target:
        return number
    result = number * FEET_PER_METER if target == "ft" else number / FEET_PER_METER
    return result


def format_length(value, unit):
    """Render a length with a sensible number of digits and a unit label."""
    digits = 4 if abs(value) < 1000 else 2
    rounded = round(value, digits)
    shown = int(rounded) if rounded == int(rounded) else rounded
    return "{} {}".format(shown, normalize_unit(unit))


def describe_conversion(value, from_unit, to_unit):
    """Build a one-line report for a single conversion."""
    source = normalize_unit(from_unit)
    target = normalize_unit(to_unit)
    converted = convert_length(value, source, target)
    arrow = "=" if source == target else "->"
    return "{} {} {}".format(format_length(float(value), source), arrow,
                             format_length(converted, target))


def parse_request(text):
    """Parse a request like '10 m in ft' or '10 in ft' into a conversion triple."""
    parts = text.replace(",", " ").split()
    if len(parts) < 3:
        raise ValueError("cannot parse request: {!r}".format(text))
    try:
        number = float(parts[0])
    except ValueError:
        raise ValueError("bad number in request: {!r}".format(text))
    middle = parts[1].lower()
    source = "m" if middle in ("in", "to", "as") else parts[1]
    return number, source, parts[-1]


def main():
    requests = ["10 m in ft", "3.28084 ft to m", "1 m to m", "5280 ft in m",
                "0.5 metres as feet"]
    for request in requests:
        try:
            value, source, target = parse_request(request)
            line = describe_conversion(value, source, target)
        except ValueError as error:
            line = "error: {}".format(error)
        print(line)

    total_meters = 0.0
    for value, unit in [(100.0, "ft"), (30.0, "m"), (12.5, "ft")]:
        total_meters += convert_length(value, unit, "m")
    summary_unit = "ft" if total_meters > 50 else "m"
    print("total: " + format_length(convert_length(total_meters, "m", summary_unit),
                                    summary_unit))


if __name__ == "__main__":
    main()

