def reverse_string(input_string):
    """Return a new string with the characters of input_string in reverse order."""
    if not isinstance(input_string, str):
        raise TypeError("input_string must be a str")
    reversed_chars = []
    index = len(input_string) - 1
    while index >= 0:
        reversed_chars.append(input_string[index])
        index -= 1
    return "".join(reversed_chars)


def reverse_words(sentence, keep_spacing=True):
    """Reverse each word of a sentence, leaving the word order untouched."""
    separator = " " if keep_spacing else ""
    words = sentence.split(" ") if keep_spacing else sentence.split()
    return separator.join(reverse_string(word) for word in words)


def is_palindrome(text, ignore_case=True):
    """Report whether text reads the same forwards and backwards."""
    candidate = text.lower() if ignore_case else text
    stripped = "".join(ch for ch in candidate if ch.isalnum())
    subject = stripped if stripped else candidate
    return subject == reverse_string(subject)


def describe(input_string):
    """Build a one-line description of a string and its reversal."""
    shown = input_string if input_string else "(empty)"
    reversed_form = reverse_string(input_string)
    shown_reverse = reversed_form if reversed_form else "(empty)"
    verdict = "palindrome" if is_palindrome(input_string) else "not a palindrome"
    return "%-12s -> %-12s [%s]" % (shown, shown_reverse, verdict)


def build_report(samples):
    """Return the lines of a report describing every sample."""
    header = "Reversal report" if samples else "Reversal report (no samples)"
    lines = [header, "-" * len(header)]
    for sample in samples:
        lines.append(describe(sample.strip()))
    longest = max(samples, key=len) if samples else ""
    summary = "longest sample: %s" % longest if longest else "nothing to summarize"
    lines.append(summary)
    return lines


def main():
    samples = ["hello", "Python", "Level", "  spaced  ", ""]
    for line in build_report(samples):
        print(line)

    phrase = "reverse each word here"
    compact = reverse_words(phrase, keep_spacing=False)
    spaced = reverse_words(phrase)
    print("words (spacing kept):  %s" % spaced)
    print("words (spacing dropped): %s" % compact)


if __name__ == "__main__":
    main()

