def is_even(number):
    """Return True when number is an even integer."""
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError("number must be an int")
    return number % 2 == 0


def parity_name(number):
    """Return the English name of the parity of number."""
    return "even" if is_even(number) else "odd"


def parse_int(text):
    """Convert a textual token into an int, returning None when impossible."""
    cleaned = text.strip()
    body = cleaned[1:] if cleaned[:1] in "+-" else cleaned
    if not body.isdigit():
        return None
    return int(cleaned)


def read_tokens(source):
    """Split a raw input string into non-empty tokens."""
    separators = "," if "," in source else None
    return [tok for tok in source.replace(";", ",").split(separators) if tok.strip()]


def next_even(number):
    """Return the smallest even integer greater than or equal to number."""
    return number if is_even(number) else number + 1


def split_by_parity(numbers):
    """Return a pair (evens, odds) preserving the original order."""
    evens, odds = [], []
    for number in numbers:
        target = evens if is_even(number) else odds
        target.append(number)
    return evens, odds


def describe(number):
    """Build a one-line description of a number's parity."""
    sign = "negative" if number < 0 else "non-negative"
    return "{:>6} is {} and {}".format(number, parity_name(number), sign)


def summarize(numbers):
    """Produce a multi-line report about the parity of the given numbers."""
    if not numbers:
        return "no numbers to inspect"
    evens, odds = split_by_parity(numbers)
    lines = [describe(number) for number in numbers]
    majority = "even" if len(evens) > len(odds) else "odd"
    verdict = "tie" if len(evens) == len(odds) else majority + " numbers dominate"
    lines.append("{} even, {} odd -> {}".format(len(evens), len(odds), verdict))
    smallest_even = evens[0] if evens else next_even(min(numbers))
    lines.append("first or nearest even value: {}".format(smallest_even))
    return "\n".join(lines)


def main():
    raw = "4, 7, -3, 0, 12, 5, 9"
    parsed = [parse_int(token) for token in read_tokens(raw)]
    numbers = [value for value in parsed if value is not None]
    rejected = len(parsed) - len(numbers)
    print("input:", raw)
    print("skipped:", rejected if rejected else "nothing")
    print(summarize(numbers))
    for probe in (4, 7):
        answer = "True" if is_even(probe) else "False"
        print("is_even({}) -> {}".format(probe, answer))


