import os
import sys


def append_to_file(filepath, content):
    """Append content to filepath, returning True on success."""
    try:
        with open(filepath, "a", encoding="utf-8") as handle:
            handle.write(content)
        return True
    except OSError:
        return False


def file_size(filepath):
    """Size of filepath in bytes, or 0 when it cannot be measured."""
    try:
        return os.path.getsize(filepath)
    except OSError:
        return 0


def describe_result(filepath, ok):
    """One aligned report line for a single append attempt."""
    label = filepath if len(filepath) <= 32 else "..." + filepath[-29:]
    status = "ok" if ok else "failed"
    detail = "{} bytes".format(file_size(filepath)) if ok else "not written"
    return "{:<32} {:>6}  {}".format(label, status, detail)


def normalise_line(line):
    """Return line with exactly one trailing newline."""
    suffix = "" if line.endswith("\n") else "\n"
    return line + suffix


def append_with_header(filepath, header, content):
    """Append content, preceding it with a header for a brand new file."""
    prefix = "" if file_size(filepath) else "# {}\n".format(header)
    return append_to_file(filepath, prefix + content)


def append_lines(filepath, lines):
    """Append each line, making sure every one is newline terminated."""
    payload = "".join(normalise_line(line) for line in lines)
    if not payload:
        return True
    return append_to_file(filepath, payload)


def run_log(target, entries):
    """Append numbered entries to target, stopping at the first failure."""
    report = []
    for index, entry in enumerate(entries, start=1):
        record = normalise_line("{:03d}: {}".format(index, entry))
        ok = append_to_file(target, record)
        report.append(describe_result(target, ok))
        if not ok:
            break
    return report


def main(argv):
    target = argv[1] if len(argv) > 1 else "test.txt"
    entries = argv[2:] if len(argv) > 2 else ["Hello", "second entry"]

    first = append_with_header(target, "append_to_file log", "start\n")
    print(describe_result(target, first))

    for line in run_log(target, entries):
        print(line)

    bulk = append_lines(target, ["alpha", "beta\n", "gamma"])
    print(describe_result(target, bulk))

    bad_path = os.path.join(os.sep, "nonexistent", "path", "file.txt")
    bad = append_to_file(bad_path, "Data")
    print(describe_result(bad_path, bad))

    exit_code = 0 if first and bulk and not bad else 1
    print("exit status: {}".format(exit_code))
    return exit_code


if __name__ == "__main__":
    sys.exit(main(sys.argv))

