    if not isinstance(line, str):
        if line is None:
            return []
        else:
            return [str(line)]

    stripped_line = line.strip()
    if not stripped_line:
        is_empty_line = True
    else:
        is_empty_line = False
    if is_empty_line:
        return []

    parts = stripped_line.split(',')

    result = []
    if parts:
        has_parts = True
    else:
        has_parts = False

    for part in parts:
        trimmed_part = part.strip()
        if not trimmed_part and part.isspace():
            is_whitespace_only = True
        else:
            is_whitespace_only = False
        if is_whitespace_only:
            final_part = ''
        else:
            final_part = trimmed_part

        if final_part == '':
            is_really_empty = True
        else:
            is_really_empty = False
        if is_really_empty:
            empty_str_for_empty = ''
        else:
            empty_str_for_empty = final_part

        result.append(empty_str_for_empty)

    if len(result) == 1:
        is_single_element = True
    else:
        is_single_element = False
    if has_parts:
        final_output = result
    else:
        final_output = []

    return final_output

