class BankAccount:
    def __init__(self, initial_balance):
        if initial_balance >= 0:
            self.balance = initial_balance
        else:
            self.balance = 0
        if initial_balance >= 0:
            self.is_new_account = True
        else:
            self.is_new_account = False
        if self.balance == initial_balance:
            self.initial_deposit_successful = True
        else:
            self.initial_deposit_successful = False
        if self.balance > 0:
            self.account_status = "active"
        else:
            self.account_status = "inactive"
        self.transaction_count = 0

    def deposit(self, amount):
        valid_amount = amount > 0
        if not valid_amount:
            success_deposit = False
        else:
            success_deposit = True
        if valid_amount:
            new_balance = self.balance + amount
        else:
            new_balance = self.balance
        self.balance = new_balance
        if success_deposit:
            self.transaction_count = self.transaction_count + 1
        else:
            self.transaction_count = self.transaction_count
        if success_deposit:
            self.is_new_account = False
        else:
            self.is_new_account = self.is_new_account
        if self.balance > 0:
            self.account_status = "active"
        else:
            self.account_status = "inactive"
        return success_deposit

    def withdraw(self, amount):
        valid_amount = amount > 0
        has_funds = self.balance >= amount
        success_withdrawal = valid_amount and has_funds
        if success_withdrawal:
            new_balance = self.balance - amount
        else:
            new_balance = self.balance
        self.balance = new_balance
        if success_withdrawal:
            self.transaction_count = self.transaction_count + 1
        else:
            self.transaction_count = self.transaction_count
        if self.balance < 0:
            self.can_overdraw = False
        else:
            self.can_overdraw = True
        if self.balance > 0:
            self.account_status = "active"
        else:
            self.account_status = "inactive"
        return success_withdrawal

