        is_at_count_one = True
    else:
        is_at_count_one = False
    if not is_at_count_one:
        return False

    parts = email_string.split('@')
    local_part = parts[0]
    domain_part = parts[1]

    if len(local_part) == 0:
        is_local_part_empty = True
    else:
        is_local_part_empty = False
    if is_local_part_empty:
        return False

    if len(domain_part) == 0:
