DIGITS = "0123456789ABCDEF"


def convert_base(number, base):
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError("number must be an integer")
    if not isinstance(base, int) or isinstance(base, bool):
        raise TypeError("base must be an integer")
    if base < 2 or base > 16:
        raise ValueError("base must be between 2 and 16")

    sign = "-" if number < 0 else ""
    value = -number if number < 0 else number
    digits = []
    while value > 0:
        digits.append(DIGITS[value % base])
        value //= base
    body = "".join(reversed(digits)) if digits else "0"
    return sign + body


def parse_base(text, base):
    stripped = text.strip().upper()
    negative = stripped.startswith("-")
    body = stripped[1:] if negative else stripped
    if not body:
        raise ValueError("empty numeral")
    total = 0
    for char in body:
        position = DIGITS.find(char)
        if position < 0 or position >= base:
            raise ValueError("invalid digit %r for base %d" % (char, base))
        total = total * base + position
    signed = -total if negative else total
    return signed


def pad(text, width):
    sign = "-" if text.startswith("-") else ""
    body = text[1:] if sign else text
    filler = "0" * (width - len(sign) - len(body))
    return sign + filler + body


def base_name(base):
    names = {2: "binary", 8: "octal", 10: "decimal", 16: "hexadecimal"}
    name = names[base] if base in names else "base-%d" % base
    return name


def report_row(number, bases, width):
    cells = [pad(convert_base(number, base), width) for base in bases]
    label = "%6d" % number
    return label + " | " + " | ".join(cells)


def table(numbers, bases):
    widths = [max(len(convert_base(n, b)) for n in numbers) for b in bases]
    width = max(widths) if widths else 1
    header = "%6s" % "dec"
    titles = [base_name(b).rjust(width) for b in bases]
    lines = [header + " | " + " | ".join(titles)]
    lines.append("-" * len(lines[0]))
    for number in numbers:
        lines.append(report_row(number, bases, width))
    return "\n".join(lines)


def main():
    bases = [2, 8, 10, 16]
    numbers = [0, 5, 10, 63, 255, -42]
    print(table(numbers, bases))
    print()
    samples = [("1010", 2), ("FF", 16), ("-77", 8), ("7B", 16)]
    for text, base in samples:
        value = parse_base(text, base)
        back = convert_base(value, base)
        status = "ok" if back == text.strip().upper() else "normalized to " + back
        print("%s (%s) = %d  [%s]" % (text, base_name(base), value, status))


if __name__ == "__main__":
    main()

