"""XOR stream cipher helpers with a small demonstration report."""

ESCAPES = {"\n": "\\n", "\t": "\\t", "\r": "\\r", "\0": "\\0"}


def _as_char(value):
    """Coerce a key given as a character or a character code to one character."""
    char = value if isinstance(value, str) else chr(value)
    if len(char) != 1:
        raise ValueError("key_char must be exactly one character")
    return char


def xor_cipher(text, key_char):
    """Encrypt or decrypt `text` by XORing each character with `key_char`."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    code = ord(_as_char(key_char))
    return "".join(chr(ord(ch) ^ code) for ch in text)


def escape_char(ch):
    """Return a printable representation of a single character."""
    code = ord(ch)
    named = ESCAPES.get(ch)
    literal = named if named is not None else "\\x%02x" % code
    printable = ch if 32 <= code < 127 else literal
    return printable


def escape(text):
    """Render a whole string with non printable characters escaped."""
    return "".join(escape_char(ch) for ch in text)


def hex_dump(text, group=4):
    """Space separated hex codes, with a wider gap between groups."""
    parts = []
    for index, ch in enumerate(text):
        gap = "  " if index % group == 0 else " "
        prefix = gap if index else ""
        parts.append(prefix + "%02x" % ord(ch))
    return "".join(parts)


def roundtrip_ok(text, key_char):
    """True when encrypting twice restores the original text."""
    return xor_cipher(xor_cipher(text, key_char), key_char) == text


def describe(text, key_char):
    """Build a one line report for a single encryption."""
    cipher = xor_cipher(text, key_char)
    status = "ok" if roundtrip_ok(text, key_char) else "FAILED"
    body = escape(cipher) if cipher else "<empty>"
    return "key=%r  %-18s -> %-22s [%s]  %s" % (
        key_char, escape(text), body, hex_dump(cipher), status)


def crack(cipher, candidates, expected):
    """Return the key whose decryption equals `expected`, or None."""
    for key in candidates:
        if xor_cipher(cipher, key) == expected:
            return key
    return None


def main():
    samples = [("Hello", "A"), ("Test", "B"), ("", "Z"), ("XOR is symmetric!", " ")]
    for text, key in samples:
        print(describe(text, key))

    secret = "attack at dawn"
    hidden = xor_cipher(secret, "k")
    alphabet = [chr(code) for code in range(32, 127)]
    key = crack(hidden, alphabet, secret)
    answer = ("key recovered: %r" % key) if key else "no key found"
    print(answer)

    zero_keyed = xor_cipher(secret, "\0")
    note = "unchanged" if zero_keyed == secret else "changed"
    print("zero key leaves text %s" % note)


if __name__ == "__main__":
    main()

