def normalize_unit(unit):
    """Return the canonical single-letter symbol for a temperature unit."""
    text = unit.strip().replace('\u00b0', '')
    symbol = text[0].upper() if text else 'C'
    return symbol


def parse_reading(text):
    """Split a string such as '98.6 F' into a numeric value and a unit symbol."""
    cleaned = text.strip().replace('\u00b0', '').replace(' ', '')
    has_unit = cleaned[-1:].upper() in ('C', 'F', 'K')
    unit = cleaned[-1] if has_unit else 'C'
    number = cleaned[:-1] if has_unit else cleaned
    return float(number), normalize_unit(unit)


def to_celsius(value, unit):
    """Convert a value expressed in `unit` into degrees Celsius."""
    unit = normalize_unit(unit)
    if unit == 'F':
        celsius = (value - 32.0) * 5.0 / 9.0
    elif unit == 'K':
        celsius = value - 273.15
    else:
        celsius = float(value)
    return float(celsius)


def from_celsius(celsius, unit):
    """Convert degrees Celsius into the requested unit."""
    unit = normalize_unit(unit)
    if unit == 'F':
        result = celsius * 9.0 / 5.0 + 32.0
    elif unit == 'K':
        result = celsius + 273.15
    else:
        result = float(celsius)
    return float(result)


def convert_temperature(value, unit_from, unit_to):
    """Convert `value` from `unit_from` to `unit_to` and return a float."""
    source = normalize_unit(unit_from)
    target = normalize_unit(unit_to)
    result = float(value) if source == target else from_celsius(to_celsius(value, source), target)
    return result


def is_physical(value, unit):
    """True when `value` is at or above absolute zero for its unit."""
    return to_celsius(float(value), unit) >= -273.15 - 1e-9


def unit_name(unit):
    """Human readable name of a unit symbol."""
    return {'C': 'Celsius', 'F': 'Fahrenheit', 'K': 'Kelvin'}[normalize_unit(unit)]


def format_temperature(value, unit, digits=2):
    """Render a temperature with its unit, using a degree sign where suitable."""
    unit = normalize_unit(unit)
    suffix = ' K' if unit == 'K' else ' \u00b0' + unit
    rounded = round(float(value), digits)
    shown = 0.0 if rounded == 0 else rounded
    return '{0:.{1}f}{2}'.format(shown, digits, suffix)


def describe(value, unit):
    """Short qualitative description of a temperature."""
    if not is_physical(value, unit):
        return format_temperature(value, unit) + ' is below absolute zero'
    celsius = to_celsius(value, unit)
    if celsius <= 0.0:
        phase = 'ice'
    elif celsius >= 100.0:
        phase = 'steam'
    else:
        phase = 'liquid'
    comfort = 'mild' if celsius < 28.0 else 'hot'
    return '{0} ({1} water, {2})'.format(format_temperature(value, unit), phase, comfort)


def conversion_report(readings, targets):
    """Build report lines converting each parsed reading into every target unit."""
    lines = []
    for text in readings:
        value, unit = parse_reading(text)
        lines.append(describe(value, unit))
        for target in targets:
            converted = convert_temperature(value, unit, target)
            arrow = '=' if normalize_unit(target) == unit else '->'
            lines.append('  {0} {1} {2} ({3})'.format(
                format_temperature(value, unit), arrow,
                format_temperature(converted, target), unit_name(target)))
    return lines


def main():
    readings = ['0 C', '273.15 K', '98.6 F', '-500 C', '150 C']
    for line in conversion_report(readings, ['C', 'F', 'K']):
        print(line)


if __name__ == '__main__':
    main()

