import sys


def _require_text(label, value):
    """Validate that a caller-supplied argument really is a string."""
    if not isinstance(value, str):
        kind = type(value).__name__
        raise TypeError("%s must be a str, got %s" % (label, kind))
    return value


def find_occurrence_positions(main_string, sub_string, overlapping=True):
    """Return the start indices where sub_string occurs, ignoring case."""
    haystack = _require_text("main_string", main_string).lower()
    needle = _require_text("sub_string", sub_string).lower()
    if not needle:
        return []
    step = 1 if overlapping else len(needle)
    positions = []
    index = haystack.find(needle)
    while index != -1:
        positions.append(index)
        index = haystack.find(needle, index + step)
    return positions


def count_substring_occurrences_ci(main_string, sub_string):
    """Count case-insensitive, non-overlapping occurrences of sub_string."""
    return len(find_occurrence_positions(main_string, sub_string, overlapping=False))


def shorten(text, limit):
    """Clip text so a report line stays readable."""
    if len(text) <= limit:
        return text
    return text[: limit - 3] + "..."


def describe_positions(positions):
    if not positions:
        return "no matches"
    prefix = "index" if len(positions) == 1 else "indices"
    listed = ", ".join(str(p) for p in positions)
    return "%s %s" % (prefix, listed)


def format_report(main_string, sub_string, limit=40):
    """Build a one-line summary of the search result."""
    total = count_substring_occurrences_ci(main_string, sub_string)
    overlaps = find_occurrence_positions(main_string, sub_string, overlapping=True)
    noun = "time" if total == 1 else "times"
    target = repr(sub_string) if sub_string else "the empty string"
    extra = " (overlapping: %d)" % len(overlaps) if len(overlaps) != total else ""
    return "%s appears %d %s in '%s' at %s%s" % (
        target,
        total,
        noun,
        shorten(main_string, limit),
        describe_positions(overlaps),
        extra,
    )


def main(argv):
    if len(argv) < 3:
        print("usage: %s TEXT SUBSTRING [WIDTH]" % argv[0])
        return 2
    limit = int(argv[3]) if len(argv) > 3 else 40
    print(format_report(argv[1], argv[2], limit))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

