def normalize_shift(shift):
    """Reduce an arbitrary integer shift to the range 0..25."""
    return shift % 26


def shift_char(ch, shift):
    """Shift a single ASCII letter, leaving every other character untouched."""
    if not ch.isalpha() or not ch.isascii():
        return ch
    base = ord('a') if ch.islower() else ord('A')
    return chr(base + (ord(ch) - base + shift) % 26)


def caesar_encrypt(text, shift):
    """Encrypt text with a Caesar cipher, preserving case and punctuation."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    amount = normalize_shift(shift)
    result = text if amount == 0 else "".join(shift_char(c, amount) for c in text)
    return result


def caesar_decrypt(text, shift):
    """Undo caesar_encrypt for the same shift."""
    return caesar_encrypt(text, -normalize_shift(shift))


def letter_counts(text):
    """Count ASCII letters case-insensitively."""
    counts = {}
    for ch in text.lower():
        if ch.isalpha() and ch.isascii():
            counts[ch] = counts.get(ch, 0) + 1
    return counts


def score_english(text):
    """Higher is more English-like, based on common-letter frequency."""
    weights = {'e': 12.7, 't': 9.1, 'a': 8.2, 'o': 7.5, 'i': 7.0,
               'n': 6.7, 's': 6.3, 'h': 6.1, 'r': 6.0, 'd': 4.3}
    counts = letter_counts(text)
    total = sum(counts.values())
    raw = sum(weights.get(letter, 0.0) * n for letter, n in counts.items())
    score = 0.0 if total == 0 else raw / total
    return score


def crack(ciphertext):
    """Guess the shift used to produce ciphertext."""
    scored = [(score_english(caesar_decrypt(ciphertext, candidate)), candidate)
              for candidate in range(26)]
    letters = sum(letter_counts(ciphertext).values())
    guess = max(scored)[1] if letters else 0
    return guess


def describe(original, shift):
    """Build a one-line report about encrypting original with shift."""
    encrypted = caesar_encrypt(original, shift)
    guessed = crack(encrypted)
    verdict = "recovered" if guessed == normalize_shift(shift) else "missed"
    round_trip = caesar_decrypt(encrypted, shift)
    integrity = "ok" if round_trip == original else "corrupt"
    return "{!r} +{} -> {!r} [{}, guess={}, {}]".format(
        original, shift, encrypted, integrity, guessed, verdict)


def main():
    samples = [("ABC", 1), ("Hello, World!", 3), ("xyz", 3),
               ("The quick brown fox jumps over the lazy dog", 13),
               ("Attack at dawn; bring supplies.", -5)]
    for text, shift in samples:
        print(describe(text, shift))
    secret = caesar_encrypt("Meet me in the old library at noon", 7)
    found = crack(secret)
    plain = caesar_decrypt(secret, found)
    label = "plaintext" if score_english(plain) > score_english(secret) else "still scrambled"
    print("cracked with shift {}: {} ({})".format(found, plain, label))


if __name__ == "__main__":
    main()

