def validate_sequence(numbers):
    """Check that `numbers` really is 1..N+1 with exactly one value absent."""
    if not numbers:
        raise ValueError("sequence must contain at least one number")
    limit = len(numbers) + 1
    seen = set()
    for value in numbers:
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("sequence must contain only integers")
        if value in seen:
            raise ValueError("duplicate value %d in sequence" % value)
        if value < 1 or value > limit:
            bound = "below 1" if value < 1 else "above %d" % limit
            raise ValueError("value %d is %s" % (value, bound))
        seen.add(value)
    return limit


def find_missing_element(numbers):
    """Return the single value of 1..len(numbers)+1 that is absent."""
    limit = validate_sequence(numbers)
    expected = limit * (limit + 1) // 2
    return expected - sum(numbers)


def describe_position(missing, limit):
    """Name the spot the missing value would have occupied."""
    tail = "the end" if missing == limit else "the middle"
    spot = "the start" if missing == 1 else tail
    return spot


