def clean_ratings(raw_ratings):
    """Keep only numeric ratings, discarding anything that is not a real number."""
    values = raw_ratings if isinstance(raw_ratings, (list, tuple)) else [raw_ratings]
    cleaned = []
    for value in values:
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            cleaned.append(float(value))
    return cleaned


def get_average_movie_rating(movie_ratings):
    """Return a dict mapping each movie title to the average of its ratings."""
    averages = {}
    for title, raw_ratings in movie_ratings.items():
        ratings = clean_ratings(raw_ratings)
        averages[title] = sum(ratings) / len(ratings) if ratings else 0.0
    return averages


def rating_count(movie_ratings, title):
    """Number of usable ratings recorded for a title."""
    return len(clean_ratings(movie_ratings.get(title, [])))


def rank_movies(averages, movie_ratings, min_votes=1):
    """Sort titles by average descending, keeping only movies with enough votes."""
    eligible = [t for t in averages if rating_count(movie_ratings, t) >= min_votes]
    pool = eligible if eligible else list(averages)
    return sorted(pool, key=lambda t: (-averages[t], t))


def star_bar(average, scale=5):
    filled = int(round(average))
    capped = filled if filled <= scale else scale
    return "*" * capped + "." * (scale - capped)


def describe(title, average, votes):
    vote_word = "vote" if votes == 1 else "votes"
    label = f"{average:.2f}" if votes else "unrated"
    return f"{title:<12} {star_bar(average):<6} {label:>8} ({votes} {vote_word})"


def build_report(movie_ratings, min_votes=1):
    averages = get_average_movie_rating(movie_ratings)
    order = rank_movies(averages, movie_ratings, min_votes)
    lines = []
    for title in order:
        votes = rating_count(movie_ratings, title)
        lines.append(describe(title, averages[title], votes))
    rated = [averages[t] for t in order if rating_count(movie_ratings, t)]
    overall = sum(rated) / len(rated) if rated else 0.0
    verdict = "recommended" if overall >= 3.5 else "mixed reception"
    lines.append(f"{'OVERALL':<12} {star_bar(overall):<6} {overall:>8.2f} ({verdict})")
    return "\n".join(lines)


def main():
    catalogue = {
        "Movie A": [5, 4, 5],
        "Movie B": [3, 2],
        "Movie C": [],
        "Movie D": [10],
        "Movie E": [4, "bad", 5, None],
    }
    threshold = 2 if len(catalogue) > 3 else 1
    print(build_report(catalogue, threshold))
    best = rank_movies(get_average_movie_rating(catalogue), catalogue, threshold)[0]
    print(f"\nTop pick with at least {threshold} votes: {best}")


if __name__ == "__main__":
    main()

