def enqueue(queue, item):
    queue.append(item)


def dequeue(queue):
    item = queue.pop(0) if queue else None
    return item


def peek(queue):
    front = queue[0] if queue else None
    return front


def size(queue):
    return len(queue)


def format_queue(queue):
    body = " <- ".join(repr(item) for item in queue) if queue else "(empty)"
    return "front [ " + body + " ] back"


def parse_command(line):
    parts = line.split()
    if not parts:
        return None, None
    name = parts[0].lower()
    argument = parts[1] if len(parts) > 1 else None
    return name, argument


def coerce(text):
    try:
        return int(text)
    except ValueError:
        return text


def run_command(queue, line):
    name, argument = parse_command(line)
    if name is None:
        return "ignored blank line"
    if name == "enqueue":
        if argument is None:
            return "enqueue needs a value"
        value = coerce(argument)
        enqueue(queue, value)
        return "enqueued " + repr(value)
    if name == "dequeue":
        item = dequeue(queue)
        outcome = "dequeued nothing" if item is None else "dequeued " + repr(item)
        return outcome
    if name == "peek":
        front = peek(queue)
        label = "nothing" if front is None else repr(front)
        return "front is " + label
    if name == "size":
        count = size(queue)
        plural = "item" if count == 1 else "items"
        return "%d %s waiting" % (count, plural)
    return "unknown command " + repr(name)


def run_script(lines):
    queue = []
    report = []
    for number, line in enumerate(lines, start=1):
        outcome = run_command(queue, line.strip())
        report.append("%2d. %-22s %s" % (number, outcome, format_queue(queue)))
    return queue, report


