from urllib.parse import unquote_plus


def split_query(url):
    """Return the query portion of a URL, ignoring any fragment."""
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    hash_at = url.find('#')
    body = url[:hash_at] if hash_at != -1 else url
    mark = body.find('?')
    return body[mark + 1:] if mark != -1 else ''


def split_pair(chunk):
    """Split a single 'key=value' chunk into a decoded (key, value) tuple."""
    eq = chunk.find('=')
    raw_key = chunk[:eq] if eq != -1 else chunk
    raw_value = chunk[eq + 1:] if eq != -1 else ''
    return unquote_plus(raw_key), unquote_plus(raw_value)


def parse_url_params(url):
    """Parse the query parameters of a URL into a dictionary."""
    query = split_query(url)
    params = {}
    for chunk in query.split('&'):
        if not chunk:
            continue
        key, value = split_pair(chunk)
        if key:
            params[key] = value
    return params


def parse_url_params_multi(url):
    """Like parse_url_params, but keeps every value for repeated keys."""
    grouped = {}
    for key, value in parse_pairs(url):
        bucket = grouped[key] if key in grouped else []
        bucket.append(value)
        grouped[key] = bucket
    return grouped


def parse_pairs(url):
    """Yield the decoded (key, value) pairs of a URL in their original order."""
    for chunk in split_query(url).split('&'):
        if chunk:
            key, value = split_pair(chunk)
            if key:
                yield key, value


def format_params(params):
    """Render a parameter mapping as an aligned, human readable report."""
    if not params:
        return '(no query parameters)'
    width = max(len(k) for k in params)
    lines = []
    for key, value in params.items():
        shown = value if value != '' else '(empty)'
        lines.append('{0:<{1}} = {2}'.format(key, width, shown))
    return '\n'.join(lines)


def main():
    urls = [
        'http://example.com?name=Alice&age=30',
        'http://example.com/path',
        'https://example.com/s?q=hello+world&tag=a&tag=b&flag=#frag',
    ]
    for url in urls:
        params = parse_url_params(url)
        multi = parse_url_params_multi(url)
        repeated = [k for k, v in multi.items() if len(v) > 1]
        print(url)
        print(format_params(params))
        note = 'repeated keys: ' + ', '.join(repeated) if repeated else 'no repeated keys'
        print(note)
        print()


if __name__ == '__main__':
    main()

