import math

def calculate_triangle_perimeter(side1, side2, side3):
    return side1 + side2 + side3

def format_length(value):
    rounded = round(value, 4)
    text = str(int(rounded)) if float(rounded).is_integer() else f"{rounded:g}"
    return text

def classify_shape(side1, side2, side3):
    distinct = len({side1, side2, side3})
    if distinct == 1:
        return "equilateral"
    shape = "isosceles" if distinct == 2 else "scalene"
    return shape

def classify_angle(side1, side2, side3):
    a, b, c = sorted((side1, side2, side3))
    legs = a * a + b * b
    longest = c * c
    tolerance = 1e-9 * max(1.0, longest)
    if abs(legs - longest) <= tolerance:
        return "right"
    angle = "obtuse" if legs < longest else "acute"
    return angle

def triangle_area(side1, side2, side3):
    s = calculate_triangle_perimeter(side1, side2, side3) / 2
    product = s * (s - side1) * (s - side2) * (s - side3)
    safe = product if product > 0 else 0.0
    return math.sqrt(safe)

def size_label(perimeter):
    if perimeter < 10:
        return "tiny"
    label = "medium" if perimeter < 100 else "large"
    return label

def is_valid_triangle(side1, side2, side3):
    sides = (side1, side2, side3)
    if any(not isinstance(x, (int, float)) or isinstance(x, bool) for x in sides):
        return False
    if any(x <= 0 for x in sides):
        return False
    a, b, c = sorted(sides)
    return a + b > c

def describe_triangle(side1, side2, side3):
    if not is_valid_triangle(side1, side2, side3):
        return "invalid triangle: " + ", ".join(str(x) for x in (side1, side2, side3))
    perimeter = calculate_triangle_perimeter(side1, side2, side3)
    shape = classify_shape(side1, side2, side3)
    angle = classify_angle(side1, side2, side3)
    area = triangle_area(side1, side2, side3)
    return (f"{shape} {angle} triangle ({size_label(perimeter)}): "
            f"perimeter={format_length(perimeter)}, area={format_length(area)}")

def perimeter_report(triangles):
    lines = []
    total = 0.0
    valid_count = 0
    for sides in triangles:
        lines.append(describe_triangle(*sides))
        if is_valid_triangle(*sides):
            total += calculate_triangle_perimeter(*sides)
            valid_count += 1
    average = total / valid_count if valid_count else 0.0
    summary = f"{valid_count} valid triangle(s), total perimeter {format_length(total)}"
    tail = f", average {format_length(average)}" if valid_count else ", no average available"
    lines.append(summary + tail)
    return "\n".join(lines)

def main():
    samples = [(3, 4, 5), (7.5, 6, 8.5), (2, 2, 2), (10, 10, 4), (120, 130, 50), (1, 2, 9)]
    print(perimeter_report(samples))
    first = calculate_triangle_perimeter(3, 4, 5)
    second = calculate_triangle_perimeter(7.5, 6, 8.5)
    bigger = "first" if first > second else "second"
    print(f"Between {format_length(first)} and {format_length(second)}, the {bigger} is bigger.")

if __name__ == "__main__":
    main()

