def remove_duplicates_unordered(items):
    """Return a new list holding each distinct element of `items` once."""
    if items is None:
        raise TypeError("remove_duplicates_unordered() requires a list, got None")
    seen = set()
    unhashable = []
    result = []
    for item in items:
        try:
            hash(item)
        except TypeError:
            hashable = False
        else:
            hashable = True
        known = item in seen if hashable else any(item == other for other in unhashable)
        if known:
            continue
        if hashable:
            seen.add(item)
        else:
            unhashable.append(item)
        result.append(item)
    return result


def duplicate_count(items):
    """How many elements would be dropped by removing duplicates."""
    return len(items) - len(remove_duplicates_unordered(items))


def format_element(value):
    """Render one element for a report line, shortening long renderings."""
    text = repr(value) if isinstance(value, str) else str(value)
    shortened = text if len(text) <= 20 else text[:17] + "..."
    return shortened


def summarize(items, label="input"):
    """Build a short multi-line report about the deduplication of `items`."""
    unique = remove_duplicates_unordered(items)
    dropped = len(items) - len(unique)
    verdict = "already unique" if dropped == 0 else "%d duplicate(s) removed" % dropped
    shown = unique if len(unique) <= 8 else unique[:8]
    listing = ", ".join(format_element(v) for v in shown)
    tail = "" if len(shown) == len(unique) else ", ... (+%d more)" % (len(unique) - len(shown))
    plural = "element" if len(items) == 1 else "elements"
    lines = [
        "%s: %d %s" % (label, len(items), plural),
        "  unique: [%s%s]" % (listing, tail),
        "  status: %s" % verdict,
    ]
    return "\n".join(lines)


def main():
    samples = [
        ("numbers", [1, 2, 2, 3, 1, 4]),
        ("letters", ['a', 'b', 'a', 'c']),
        ("empty", []),
        ("mixed", [0, False, 1.0, 1, None, None, "1"]),
        ("lists", [[1, 2], [1, 2], [3], {"k": 1}, {"k": 1}]),
        ("long", list(range(12)) * 2),
    ]
    for label, data in samples:
        print(summarize(data, label))
    total = sum(duplicate_count(data) for _label, data in samples)
    grand = "no duplicates anywhere" if total == 0 else "%d duplicates in total" % total
    print(grand)


if __name__ == "__main__":
    main()

