            known = item in seen
        else:
            known = any(item == other for other in unhashable)
        if known:
            continue
        if hashable:
            seen.add(item)
        else:
            unhashable.append(item)
        result.append(item)
    return result


def duplicate_count(items):
    """How many elements would be dropped by removing duplicates."""
    return len(items) - len(remove_duplicates_unordered(items))


def format_element(value):
    """Render one element for a report line, shortening long renderings."""
    if isinstance(value, str):
        text = repr(value)
    else:
        text = str(value)
    if len(text) <= 20:
        shortened = text
    else:
        shortened = text[:17] + "..."
    return shortened


def summarize(items, label="input"):
    """Build a short multi-line report about the deduplication of `items`."""
    unique = remove_duplicates_unordered(items)
    dropped = len(items) - len(unique)
    if dropped == 0:
        verdict = "already unique"
    else:
        verdict = "%d duplicate(s) removed" % dropped
    if len(unique) <= 8:
        shown = unique
    else:
        shown = unique[:8]
    listing = ", ".join(format_element(v) for v in shown)
    if len(shown) == len(unique):
        tail = ""
    else:
        tail = ", ... (+%d more)" % (len(unique) - len(shown))
    if len(items) == 1:
        plural = "element"
    else:
        plural = "elements"
    lines = [
        "%s: %d %s" % (label, len(items), plural),
        "  unique: [%s%s]" % (listing, tail),
        "  status: %s" % verdict,
    ]
    return "\n".join(lines)


