MARKERS = {"at": "=", "above": "^", "below": "v"}


def calculate_average(numbers):
    """Return the arithmetic mean of numbers, or 0.0 for an empty list."""
    total = float(sum(numbers))
    return 0.0 if not numbers else total / len(numbers)


def parse_number(text):
    """Convert a token to int or float, returning None when it is not numeric."""
    token = text.strip()
    cleaned = token[1:] if token.startswith("+") else token
    try:
        value = float(cleaned) if ("." in cleaned or "e" in cleaned.lower()) else int(cleaned)
    except ValueError:
        return None
    return value


def parse_series(line, separator=None):
    """Split a line into numbers, ignoring tokens that cannot be parsed."""
    tokens = line.split(separator) if separator else line.split()
    numbers = []
    for token in tokens:
        value = parse_number(token)
        if value is not None:
            numbers.append(value)
    return numbers


def format_number(value, places=2):
    """Render a number without a trailing .0 when it is whole."""
    rounded = round(float(value), places)
    return str(int(rounded)) if rounded == int(rounded) else f"{rounded:.{places}f}"


def describe(label, numbers):
    """Build a one-line report for a labelled series."""
    average = calculate_average(numbers)
    count = len(numbers)
    noun = "value" if count == 1 else "values"
    body = "no data" if count == 0 else f"{count} {noun}, mean {format_number(average)}"
    return f"{label}: {body}"


def compare_to_average(numbers):
    """Classify each value relative to the mean of the series."""
    average = calculate_average(numbers)
    result = []
    for value in numbers:
        if value == average:
            verdict = "at"
        else:
            verdict = "above" if value > average else "below"
        result.append((value, verdict))
    return result


def main():
    raw_lines = [
        "Weekdays: 1 2 3 4 5",
        "Pair: 10 20",
        "Mixed: 4 oops 8 -2",
        "Empty:",
    ]
    for raw in raw_lines:
        label, payload = raw.partition(":")[0], raw.partition(":")[2]
        numbers = parse_series(payload)
        print(describe(label.strip(), numbers))
        for value, verdict in compare_to_average(numbers):
            print(f"  {MARKERS[verdict]} {format_number(value)} is {verdict} the mean")

    all_numbers = parse_series(" ".join(raw.partition(":")[2] for raw in raw_lines))
    overall = calculate_average(all_numbers)
    spread = max(all_numbers) - min(all_numbers) if all_numbers else 0.0
    print(f"Overall mean: {format_number(overall)} (spread {format_number(spread)})")


if __name__ == "__main__":
