def normalize_binary(text):
    """Strip separators, prefix and surrounding whitespace from a binary literal."""
    cleaned = text.strip().replace("_", "") if text else ""
    body = cleaned[2:] if cleaned[:2].lower() == "0b" else cleaned
    return body


def is_binary(text):
    body = normalize_binary(text)
    return bool(body) and all(ch in "01" for ch in body)


def binary_to_gray(binary):
    """Convert a binary string to the equivalent Gray code string."""
    bits = normalize_binary(binary)
    gray = bits[0] if bits else ""
    for index in range(1, len(bits)):
        differ = bits[index] != bits[index - 1]
        bit = "1" if differ else "0"
        gray += bit
    return gray


def gray_to_binary(gray):
    """Invert the Gray code encoding, recovering the original binary string."""
    code = normalize_binary(gray)
    binary = code[0] if code else ""
    for bit in code[1:]:
        previous = binary[-1]
        flipped = "0" if previous == "1" else "1"
        nxt = flipped if bit == "1" else previous
        binary += nxt
    return binary


def describe(binary):
    """Build a one-line report for a candidate binary string."""
    if not is_binary(binary):
        return "{0!r}: not a valid binary string".format(binary)
    bits = normalize_binary(binary)
    gray = binary_to_gray(bits)
    value = int(bits, 2)
    parity = "even" if bin(value).count("1") % 2 == 0 else "odd"
    roundtrip = gray_to_binary(gray)
    status = "ok" if roundtrip == bits else "MISMATCH ({0})".format(roundtrip)
    return "{0} -> {1}  (value {2}, {3} parity, {4})".format(
        bits, gray, value, parity, status
    )


def gray_sequence(width):
    """Return the Gray codes of all binary numbers of the given width."""
    if width < 1:
        return []
    return [binary_to_gray(format(n, "0{0}b".format(width))) for n in range(2 ** width)]


def main():
    samples = ["000", "1011", "0b1111_0000", "1", "10201", ""]
    for sample in samples:
        print(describe(sample))

    width = 3
    codes = gray_sequence(width)
    print("Gray sequence for width {0}:".format(width))
    for position, code in enumerate(codes):
        neighbour = codes[position + 1] if position + 1 < len(codes) else codes[0]
        changed = sum(1 for a, b in zip(code, neighbour) if a != b)
        note = "adjacent" if changed == 1 else "distance {0}".format(changed)
        print("  {0:>2}: {1} -> {2} ({3})".format(position, code, neighbour, note))


if __name__ == "__main__":
