import random

HEAD_SYMBOLS = ('H', '1')
TAIL_SYMBOLS = ('T', '0')

def normalize_flips(flips):
    """Return an upper-case flip string, tolerating spaces and 0/1 notation."""
    cleaned = []
    for ch in flips.strip():
        if ch.isspace():
            continue
        upper = ch.upper()
        if upper in HEAD_SYMBOLS:
            cleaned.append('H')
        elif upper in TAIL_SYMBOLS:
            cleaned.append('T')
        else:
            raise ValueError("invalid coin flip character: %r" % ch)
    return ''.join(cleaned)

def longest_coin_flip_streak(flips):
    """Length of the longest run of identical consecutive flips."""
    sequence = normalize_flips(flips)
    if not sequence:
        return 0
    best = current = 1
    previous = sequence[0]
    for flip in sequence[1:]:
        current = current + 1 if flip == previous else 1
        if current > best:
            best = current
        previous = flip
    return best

def streak_details(flips):
    """Return (side, length, start_index) of the first longest streak."""
    sequence = normalize_flips(flips)
    longest = longest_coin_flip_streak(sequence)
    if longest == 0:
        return (None, 0, -1)
    run_start = 0
    for index in range(1, len(sequence) + 1):
        ended = index == len(sequence) or sequence[index] != sequence[run_start]
        if ended:
            if index - run_start == longest:
                return (sequence[run_start], longest, run_start)
            run_start = index
    return (sequence[0], longest, 0)

def simulate_flips(count, rng=None):
    """Generate a random flip string of the requested length."""
    source = rng if rng is not None else random.Random()
    return ''.join(source.choice('HT') for _ in range(count))

def describe(flips):
    side, length, start = streak_details(flips)
    if length == 0:
        return "no flips recorded"
    name = 'heads' if side == 'H' else 'tails'
    plural = 'flip' if length == 1 else 'flips'
    return "longest streak: %d %s of %s starting at index %d" % (length, plural, name, start)

def main():
    samples = ['HHHTTTHHHH', 'HTHTHT', '', 'H T T H H H H T T', '1100011']
    for sample in samples:
        label = repr(sample) if sample else "'' (empty)"
        print("%-22s -> %d" % (label, longest_coin_flip_streak(sample)))
        print("    " + describe(sample))
    rng = random.Random(2026)
    trial = simulate_flips(40, rng)
    print("simulated: " + trial)
    print("    " + describe(trial))
    heads = trial.count('H')
    tails = trial.count('T')
    fairness = 'balanced' if abs(heads - tails) <= 4 else 'lopsided'
    print("    sample looks %s (%d heads, %d tails)" % (fairness, heads, tails))

if __name__ == '__main__':
    main()

